INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words) VALUES
(1,'가계수지','가정에서 일정 기간의 수입(명목소득)과 지출을 비교해서 남았는지 모자랐는지를 표시한 것을 가계수지(Household’s Total Income and Expenditure)라 한다.','가정에서 일정 기간의 수입(명목소득)과 지출을 비교해서 남았는지 모자랐는지를 표시한 것을 가계수지(Household’s Total Income and Expenditure)라 한다. 가계수지가 흑자를 냈다면 그 가정은 벌어들인 수입 일부만을 사용했다는 것을 의미하며, 적자를 냈다면 수입 외에 빚을 추가로 얻어 사용한 것이라고 보아야 한다. 우리나라는 통계청에서 국민의 소득수준 및 생활실태를 파악하기 위해 표본으로 선정된 가계에 가계부를 나누어 주고 한 달간의 소득과 지출을 기록하도록 한 다음 이를 토대로 가계수지 통계를 작성하여 발표하고 있다. 가계부의 소득항목에는 근로소득·사업소득·재산소득·이전소득 항목이 있고, 비용항목에는 식료품비·주거비·수도광열비·보건비·교육비 항목이 있다.','','ㄱㄱㅅㅈ',ARRAY['경상수지','재정수지']::text[]),
(2,'가계순저축률','일반적으로 저축률은 저축액을 처분가능소득으로 나눈 비율을 말한다.','일반적으로 저축률은 저축액을 처분가능소득으로 나눈 비율을 말한다. 마찬가지로 가계순저축률은 가계부문의 순저축액을 가계순처분가능소득과 정부로부터 받은 사회적 현물이전 금액, 연금기금의 가계순지분 증감조정액을 합계한 금액으로 나눈 비율이다. 여기서 사회적 현물이전(Social Transfer in Kind)이란 정부 등이 가계에 현물이전의 형태로 제공하는 재화 및 서비스로서 무상교육, 보건소의 무상진료 등이 해당된다. 또한 연금기금의 가계순지분 증감조정액을 분모에 더하는 이유는 퇴직연금 등과 같이 가계가 납부한 연금부담금과 연금수취액의 차액을 반영해야 가계부문의 저축액을 정확히 구할수 있기 때문이다. 가계순저축률은 가계부문의 저축성향을 가장 잘 나타내주는 지표라고 할 수 있다. 가계순저축률(%) = {가계부문 순저축 / (가계순처분가능소득 + 사회적현물이전수취 + 연금기금의 가계순지분 증감조정)} × 100','','ㄱㄱㅅㅈㅊㄹ',ARRAY['가계처분가능소득','저축률']::text[]),
(3,'가계신용통계','가계신용통계는 가계부문에 대한 신용공급 규모를 나타내는 통계이다.','가계신용통계는 가계부문에 대한 신용공급 규모를 나타내는 통계이다. 가계신용은 금융기관뿐 아니라 정부, 판매회사 등 기타기관이 가계에 제공한 대출과 외상구매 관련 신용을 모두 포괄하는 것으로 크게 가계대출과 판매신용으로 구분된다. 현재 가계신용통계는 가교은행 2002년 말 잔액부터 분기별로 제공되고 있다. 가계신용통계는 우리나라 가계부문의 부채규모 및 변동 등을 파악하는 데 널리 활용되고 있다.','','ㄱㄱㅅㅇㅌㄱ','{}'::text[]),
(4,'가계처분가능소득','가계처분가능소득(PDI; Personal Disposable Income)은 가계가 마음대로 소비와 저축으로 처분할 수 있는 소득을 의미한다.','가계처분가능소득(PDI; Personal Disposable Income)은 가계가 마음대로 소비와 저축으로 처분할 수 있는 소득을 의미한다. 흔히 국민의 생활 수준을 파악해 볼 수 있는 지표로 1인당 국민총소득(GNI)이 널리 쓰이고 있으나 GNI에는 가계뿐 아니라 기업, 금융회사와 정부가 벌어들인 소득이 모두 포함되어 있다. 따라서 기업과 금융회사 등이 가 계 부문보다 더 많은 소득을 벌어 1인당 GNI가 높아진 경우에는 가계가 느끼는 체감경기는 전체 경기와 괴리가 있게 된다. 1인당 가계총처분가능소득(PGDI; Personal Gross Disposable Income)은 가계부문의 총처분가능소득을 연앙인구로 나누어 계산한 지표로 가계의 구매력을 가장 정확히 가늠해 볼 수 있는 소득지표이다.','','ㄱㄱㅊㅂㄱㄴㅅㄷ',ARRAY['국민총소득(GNI)']::text[]),
(5,'가교은행','청산 대상 금융기관의 자산, 부채를 임시로 넘겨받아 예금, 출금 등의 업무를 대행하고 합병, 채권채무관계 조정 등 후속조치를 수행하는 은행을 말한다.','청산 대상 금융기관의 자산, 부채를 임시로 넘겨받아 예금, 출금 등의 업무를 대행하고 합병, 채권채무관계 조정 등 후속조치를 수행하는 은행을 말한다. 금융기관이 파산한 경우예금보험공사는 예금자보호법 및 관계법령에서 정한 절차에 따라 청산, 매각, 자산부채승계, 가교은행을 통한 인수 등의 금융기관 정리수단을 통하여 부실 금융기관을 정리한다. 이 중 가교은행을 통한 인수방식은 파산은행의 처리에 상당한 시간이 소요될 것으로 예상될 때 사용되며 새로운 은행을 설립하여 자산, 부채를 포괄승계하도록 하고, 인수 희망자를 물색하는 등의 조치를 취하게 된다. 가교은행을 이용한 처리방식은 금융기관 파산에 따른 충격을 완화하고 시간적인 여유를 확보할 수 있는 장점이 있다. 가교은행은 파산 처리가 완료되면 정리대상 금융기관과 마찬가지로 없어지는 한시적 기관이다.','','ㄱㄱㅇㅎ','{}'::text[]),
(6,'가산금리','신용도 등의 차이에 따라 기준금리에 덧붙이는 금리를 가산금리(또는 스프레드, spread) 라고 한다.','신용도 등의 차이에 따라 기준금리에 덧붙이는 금리를 가산금리(또는 스프레드, spread) 라고 한다. 예를 들어 은행이 대출금리를 결정할 때 고객의 신용위험에 따라 조달금리에 추가하는 금리를 말한다. 한편 만기가 길어지면 추가로 가산되는 금리를 기간 가산금리 (텀스프레드, term spread)라고 하는데 이것도 일종의 스프레드이다. 통상 신용도가 높으면 가산금리가 낮고, 신용도가 낮으면 가산금리 즉 스프레드는 커진다. 한편 채권시장에서는 비교대상이 되는 금융상품의 금리에 대비한 차이를 스프레드라고 한다. 보통 해외에서 채권을 발행할 때 동일한 만기의 미국 국채(Treasury Bond) 금리나 무위험지표금리 (RFR; Risk-Free Rate)가 기준금리가 되고 여기에 신용도 등에 따라 가산금리가 붙어서 발행되는게 보통이다. 실제로 우리나라는 지난 1997년 외환위기 당시에 해외에서 채권을 발행할 때 높은 가산금리를 지불한 경험이 있다. 기준금리와의 차이를 나타내는 가산금리또는 스프레드는 보통 베이시스 포인트(bp; basis point)로 나타내는데 예를 들면 0.5% 의 금리격차를 50bp로 표기하고 1%는 100bp로 표시된다.','','ㄱㅅㄱㄹ',ARRAY['무위험지표금리(RFR: Risk-Free Rate)','신용스프레드']::text[]),
(7,'가상자산','가상자산(Virtual Asset)은 분산원장 및 암호화 기술을 바탕으로 민간에 의해 디지털 토큰형태로 발행되어 전자적으로 거래 또는 이전 가능한 자산이다.','가상자산(Virtual Asset)은 분산원장 및 암호화 기술을 바탕으로 민간에 의해 디지털 토큰형태로 발행되어 전자적으로 거래 또는 이전 가능한 자산이다. 「가상자산 이용자 보호 등 에 관한 법률」에서는 “경제적 가치를 지닌 것으로서 전자적으로 거래 또는 이전될 수 있는 전자적 증표와 그에 관한 일체의 권리”로 정의하며, 발행인이 사용처와 용도를 제한한 것, 게임물의 이용을 통해 획득한 결과물, 전자화폐, 전자증권, 전자어음 등은 가상자산에서 제외하고 있다. 가상자산은 전통적인 현금, 예금 등의 화폐와는 구별되는 새로운 형태의 자산으로서 일부에서 투자 및 지급수단으로 활용되고 있으나, 가격 변동성이 크고, 신뢰성과 안정성 측면에서 기존 금융자산과 차이가 있다. 국제자금세탁방지기구(FATF; Financial Action Task Force)는 “디지털 방식으로 거래, 이전될 수 있으며, 지급 또는 투자 목적으로 사용될 수 있는 가치의 디지털 증표(digital representation of value)”로 정의하며 법정통화의 디지털 증표라고 할 수 있는 중앙은행 디지털화폐(CBDC)나 증권 등 간접금융/직접금융기존 금융자산의 디지털 표현 형태는 포함되지 않는다. 한국은행은 가상자산이 금융시스템과 통화정책, 지급결제시스템에 미치는 영향에 대해 지속적으로 연구하고 있으며, 국제기구 등과의 협력을 통해 가상자산 시장의 투명성 및 이용자 보호 강화 등을 위한 정책적 ㄱ 기반 마련을 위해 노력하고 있다.','','ㄱㅅㅈㅅ',ARRAY['블록체인','비트코인','중앙은행 디지털화폐(CBDC)']::text[]),
(8,'가상자산공개(ICO)','가상자산공개(ICO; Initial Coin Offering)는 주로 혁신적인 신생기업(startup)이 가상자산(virtual asset) 또는 디지털 토큰(digital token, 일종의…','가상자산공개(ICO; Initial Coin Offering)는 주로 혁신적인 신생기업(startup)이 가상자산(virtual asset) 또는 디지털 토큰(digital token, 일종의 투자증명)을 이용하여 자금을 조달하는 크라우드펀딩(crowd funding)의 한 방식이다. 가상자산공개(ICO)에서 새로 발행된 가상자산은 법화(legal tender) 또는 비트코인 등 기존의 가상자산과 교환되어 투자자에게 팔린다. 가상자산공개는 거래소에 상장하려는 기업이 투자자에게 자기 주식을 처음 공개적으로 매도하는 기업공개(IPO; Initial Public Offering)에서 연유되었다고 볼 수 있다. 기업공개(IPO)에 참여한 투자자는 해당 기업의 소유권과 관련하여 주식을 획득한다. 반면 가상자산공개(ICO)에 참여한 투자자는 해당 신생기업의 코인 (coins) 또는 토큰을 얻는데, 이는 해당 기업이 제안한 프로젝트가 나중에 성공했을 경우평가될 수 있는 가치(value)로 볼 수 있다. ICO는 이더리움(Ethereum)을 포함한 다양한 분산원장 기반 블록체인 네트워크에서 이뤄지고 있다. 우리나라의 경우 향후 논의를 거쳐 ICO를 포함한 가상자산 전반의 발행 및 유통 관련 사항을 가상자산 관련 법률에서 규제할 것으로 보인다.','','ㄱㅅㅈㅅㄱㄱ()',ARRAY['가상자산','블록체인','비트코인','빅데이터']::text[]),
(9,'간접금융/직접금융','자금 잉여주체와 자금 부족주체 사이에 은행이나 저축은행 신용협동기구 등 금융기관이 개입하여 자금을 중개하는 방식을 간접금융(Indirect Financing)이라고 한다.','자금 잉여주체와 자금 부족주체 사이에 은행이나 저축은행 신용협동기구 등 금융기관이 개입하여 자금을 중개하는 방식을 간접금융(Indirect Financing)이라고 한다. 즉 금융기관이 일반 대중으로부터 예금을 받아 기업 등 다른 경제주체에게 대출해 주는 방식이다. 한편 주식, 채권 발행의 경우와 같이 자금수요자가 금융기관을 통하지 않고 금융시장에서 직접 필요자금을 조달하는 방식을 직접금융(Direct Financing)이라고 한다. 간접금융에 서는 은행이 중추적인 기능을 하고, 직접금융에서는 주식과 채권이 거래되는 자본시장이 중요한 역할을 수행한다. 직접금융과 간접금융은 상호 경쟁적일 뿐만 아니라 보완적이기도 하므로 균형적으로 발전될 필요가 있다. 직접금융과 간접금융의 상대적 비중이 어느정도이어야 이상적인지는 해당 국가의 경제발전 단계나 경제구조에 따라 달라질 수밖에 없다. 예를 들면 중소기업의 비중이 높은 국가일수록 정보의 비대칭성 문제를 완화하기위해 간접금융이 더 중요하고, 혁신산업에 의해 주도되는 경제일수록 미래의 성장 가능성을 보고 투자하고 그 위험과 이익을 공유하는 주식 등 직접금융의 역할이 더 중요할 것이 다. 일반적으로 금융시장이 발달함에 따라 직접금융 비중이 높아진다.','','ㄱㅈㄱㅇ/ㅈㅈㄱㅇ',ARRAY['금융제도','장기금융시장(자본시장)']::text[]),
(10,'간접세/직접세','조세는 납세의무자와 실제로 세금을 부담하게 되는 조세부담자가 일치하는지 여부에 따라 간접세(Indirect Tax)와 직접세(Direct Tax)로 구분된다.','조세는 납세의무자와 실제로 세금을 부담하게 되는 조세부담자가 일치하는지 여부에 따라 간접세(Indirect Tax)와 직접세(Direct Tax)로 구분된다. 납세의무자와 조세부담자가 일치하여 조세부담이 전가(轉嫁)되지 않는 조세를 직접세라고 하며, 대표적인 예로는 소득세, 법인세, 상속세, 증여세, 종합부동산세 등이 있다. 이와 달리 납세의무자와 조세부담자가 일치하지 않고 조세의 부담이 타인에게 전가되는 세금을 간접세라고 하며, 대표적인 예로는 부가가치세, 개별소비세, 주세, 인지세, 증권거래세 등이 있다. 간접세는 조세에 대한 저항이 적고 징수가 간편하여 조세수입의 확보가 용이하다는 장점이 있다. 반면, 개인의 사정을 고려할 수 없으므로 누진세율(累進稅率)을 적용하지 못하고 비례세율이 적용됨으로써 소득이 적은 자에게 상대적으로 높은 조세부담률이 적용되는 역진성(逆進性) 을 띠게 되어 공평부담의 원칙에 어긋난다는 단점이 있다. 한편, 국민계정체계에서는 조세의 실질적인 부담주체를 결정하기가 쉽지 않은 점 등을 감안하여 간접세와 직접세 대신생산 및 수입세, 소득 및 부 등에 대한 경상세, 자본세란 용어를 사용하고 있다.','','ㄱㅈㅅ/ㅈㅈㅅ','{}'::text[]),
(11,'간편 송금','간편 송금은 모바일 앱이나 온라인 서비스를 통해 상대방에게 손쉽게 금전적 가치를 거래정보저장소이전해 주는 서비스이다.','간편 송금은 모바일 앱이나 온라인 서비스를 통해 상대방에게 손쉽게 금전적 가치를 거래정보저장소이전해 주는 서비스이다. 이용이 다소 복잡하고 불편한 공인인증서나 OTP(One Time Password, 일회용 비밀번호) 없이도 비밀번호 또는 지문인식과 같은 생체인증만으로 송금이 가능하기 때문에 사용자가 편리함을 느끼게 된다. 국내에서는 토스, 카카오페이, ㄱ 네이버페이 등이 간편 송금 방식을 이용하고 있다.','','ㄱㅍㅅㄱ',ARRAY['NFC 기술']::text[]),
(12,'감독자협의회(Supervisory College)','다국적 금융기관들에 대한 효과적인 규제·감독을 위하여 다국적 금융기관의 본점이 소재한 국가(home country)의 감독 당국과 동 기관의 지점 또는 자회사가 소재한 진출국 (host…','다국적 금융기관들에 대한 효과적인 규제·감독을 위하여 다국적 금융기관의 본점이 소재한 국가(home country)의 감독 당국과 동 기관의 지점 또는 자회사가 소재한 진출국 (host country)의 감독 당국들로 구성된 정보공유 및 감독협력 협의체를 의미한다. 금융기관의 영업활동이 전 세계적으로 이루어지고 있는데 반해 규제·감독이 금융기관의 국적또는 지역기반을 중심으로 이루어지고 있는 한계를 극복하기 위하여 설립되었다.','','ㄱㄷㅈㅎㅇㅎ()','{}'::text[]),
(13,'갑기금(Capital A)','외국은행 국내지점의 대차대조표상 자본금계정으로 ① 외국은행 국내지점의 설치 및 영업행위를 위하여 본점이 한국은행 등에 외화자금을 매각하여 해당 지점에 공급한 원화 자금 ② 해당 외국은행 국내지점의…','외국은행 국내지점의 대차대조표상 자본금계정으로 ① 외국은행 국내지점의 설치 및 영업행위를 위하여 본점이 한국은행 등에 외화자금을 매각하여 해당 지점에 공급한 원화 자금 ② 해당 외국은행 국내지점의 적립금에서 전입하는 자금 ③ 외국은행 국내지점을 추가 로 설치하기 위하여 이미 국내에 설치된 외국은행 국내지점의 이월이익잉여금에서 전입하는 자금 등이 이에 해당한다. 갑기금은 금융위원회로부터 인정받은 금액에 한하여 지점별로 관리하되 각 외은지점의 갑기금은 30억원 이상이어야 한다(「은행법 시행령」 제26 조, 「은행업 감독규정」 제11조).','','ㄱㄱㄱ()',ARRAY['을기금(Capital B)']::text[]),
(14,'거래정보저장소','거래정보저장소(TR; Trade Repository)는 장외파생상품(OTC Derivatives) 거래에 대한 상세 정보를 중앙 집중적으로 수집, 보관 및 관리하는 금융시장인프라(FMI)이다.','거래정보저장소(TR; Trade Repository)는 장외파생상품(OTC Derivatives) 거래에 대한 상세 정보를 중앙 집중적으로 수집, 보관 및 관리하는 금융시장인프라(FMI)이다. 2008년 글로벌 금융위기 당시 리먼브라더스 사태에서 장외파생상품 거래의 불투명성이 위기를 증폭시킨 주된 원인으로 지목되면서, G20 정상들은 시장 투명성 강화를 위해 모든 장외파생상품 거래 정보의 보고 의무화를 합의했고, 이에 따라 TR 도입이 추진되었다. TR의 주요 역할로는 정보 집적 및 관리, 리스크 모니터링, 시장 투명성 제고, 규제 당국의 감독 지원 등을 들 수 있다. 우리나라에서는 한국거래소(Korea Exchange, KRX)가 2015년 TR사업자로 선정되어 시스템을 구축하였으며, 2021년 4월부터 장외파생상품 거래 정보 보고 의무화가 시행되면서 KRX-TR이 공식적으로 운영되고 있다.','','ㄱㄹㅈㅂㅈㅈㅅ',ARRAY['금융시장인프라']::text[]),
(15,'거시건전성 정책','개별 금융회사의 부실 방지를 목적으로 하는 미시건전성정책(Microprudential policy) 과 달리 경제전체의 금융안정을 위해 시스템 리스크(systemic risk)를 억제하는 정책을…','개별 금융회사의 부실 방지를 목적으로 하는 미시건전성정책(Microprudential policy) 과 달리 경제전체의 금융안정을 위해 시스템 리스크(systemic risk)를 억제하는 정책을 의 미한다. 구체적으로 거시건전성정책(Macroprudential policy)의 목표는 시스템 리스크에 대한 선제적 대응, 과도한 금융불균형 축적 억제, 급격한 되돌림 현상(unwinding) 완화, 금융시스템의 복원력(resilience) 강화, 금융연계성 제어 등을 통해 금융위기의 발생가능성과 실물경제에 미치는 부정적인 영향(spillover effects)을 최소화하는 데 있다. 거시건전성정책은 통화정책과 재정정책 등 여러 다른 정책과 긴밀히 관련되어 있으므로, 거시건전성정책의 수립과 집행에는 여러 정책당국 간 정보공유와 협력 및 조정이 긴요하다.','','ㄱㅅㄱㅈㅅㅈㅊ','{}'::text[]),
(16,'거액익스포저 규제','금융기관의 특정 차주 등에 대한 신용공여가 과도한 경우 해당 거래상대방의 채무불이행등의 발생시 해당 금융기관의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다.','금융기관의 특정 차주 등에 대한 신용공여가 과도한 경우 해당 거래상대방의 채무불이행등의 발생시 해당 금융기관의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다. 바젤Ⅱ에서는 이러한 편중리스크를 직접 규율하지 않고 각국 감독당국이 편중리스크를 점검·관리하도록 하였다. 우리나라는 은행법 등에서 동일인·동일차주 신용공여 한도 제도를 통해 편중리스크를 관리하고 있다. 한편 금융위기 이후 금융기관간 상호연계성에 의 한 시스템 리스크를 억제하고 편중리스크의 근본적인 관리 필요성이 대두됨에 따라 바젤위원회(BCBS)는 거액익스포저 규제를 2019년 1월 도입하였고 우리나라는 2019년 3월결제시범실시한 이후 2024년 2월부터 시행 중이다. 동 규제는 거액익스포저를 단일 거래상대방 또는 연계된 거래상대방그룹(경제적 상호의존성이 있는 거래상대방들로 구성되어 거래상대방들 중 하나가 파산하면 다른 모든 거래상대방들이 파산할 가능성이 상당히 높은 ㄱ 그룹)에 대한 익스포저의 합계가 은행 기본자본의 10% 이상인 경우로 정의하고, 거액익스포저 현황을 금융당국에 정기적으로 보고하도록 하는 한편, 거액익스포저비율(거액익스포저를 은행 기본자본으로 나눈 값)이 25%를 초과하지 못하도록 하고 있다.','','ㄱㅇㅇㅅㅍㅈㄱㅈ',ARRAY['동일인 신용공여한도제(동일인 여신한도제)','익스포저']::text[]),
(17,'거액지급시스템','참가기관 간에 주로 거액의 자기자금 또는 고객자금 이체를 위한 지급지시가 이루어지는 시스템을 말한다.','참가기관 간에 주로 거액의 자기자금 또는 고객자금 이체를 위한 지급지시가 이루어지는 시스템을 말한다. 거래 가능한 최소금액이 설정된 것은 아니나 일반적으로 금융시장에서 이루어진 금융기관간 콜거래, 증권 또는 외환매매 등 거액거래에 따른 대금이체지시를 다루기 때문에 건당 이체지시 금액이 상대적으로 크다. 또한 한 나라의 금융기관간 자금거래 대부분이 처리되는 중요시스템으로서 결제시점과 결제리스크 관리의 필요 성이 높아 주요국의 거액지급시스템은 대부분 신용리스크를 제거할 수 있는 실시간총액결제방식을 채택하고 있으며 대부분 중앙은행이 직접 운영한다. 우리나라의 한은금융망 (BOK-Wire+), 미국 연준의 Fedwire, 유럽중앙은행(ECB)의 TARGET2 등이 여기에 해당된다.','','ㄱㅇㅈㄱㅅㅅㅌ',ARRAY['지급','청산']::text[]),
(18,'결제리스크','결제리스크는 예기치 못한 사정으로 인하여 결제가 예정대로 이루어지지 않을 가능성 또는 그로 인하여 야기되는 손실발생 가능성으로 정의할 수 있다.','결제리스크는 예기치 못한 사정으로 인하여 결제가 예정대로 이루어지지 않을 가능성 또는 그로 인하여 야기되는 손실발생 가능성으로 정의할 수 있다. 이러한 결제리스크는 발생가능성이 낮더라도 실제 발생할 경우 큰 손실을 초래할 수 있다는 특성을 갖고 있다. 지급결제 규모가 지속적으로 늘어나는 가운데 정보통신기술의 발달 등 지급결제 환경 변화와 글로벌 금융위기의 영향 등으로 결제리스크에 대한 관심이 높아지고 있다. 특히 인터넷과 모바일을 이용한 다양한 지급서비스의 제공은 지급결제제도의 효율성을 제고시키고 있으나 다른 한편으로는 결제리스크의 증가에도 영향을 미치고 있다. 결제리스크는 거래에 따른 지급 시점과 청산·결제시점간의 차이, 청산·결제방식, 금융시장인프라 참가기관의 재무건전성 등 여러 요인에 의해 발생할 수 있다. 결제리스크를 유형별로 세분화하면신용리스크(credit risk), 유동성리스크(liquidity risk), 운영리스크(operational risk), 법률리스크(legal risk), 시스템리스크(systemic risk) 등이 있다.','','ㄱㅈㄹㅅㅋ',ARRAY['지급결제시스템','지급결제제도 감시']::text[]),
(19,'결제부족자금 공동분담제','결제부족자금 공동분담제(Loss-Sharing)는 참가기관이 거래에 따른 지급의무를 이행하지않는 경우 지급되지 않은 채무를 여타 참가기관들이 공동분담함으로써 결제가 완료되도록보장하는 방안이다.','결제부족자금 공동분담제(Loss-Sharing)는 참가기관이 거래에 따른 지급의무를 이행하지않는 경우 지급되지 않은 채무를 여타 참가기관들이 공동분담함으로써 결제가 완료되도록보장하는 방안이다. 이는 특정기관의 지급불이행이 연쇄적으로 여타 기관의 결제불이행을 유발함으로써 발생할 수 있는 전체 지급결제시스템의 붕괴와 금융혼란을 방지하기 위한 것이다. 미지급채무의 분담기준으로는 참가기관의 규모, 시스템 이용실적, 참가기관의 신용한 도액 등을 사용한다. 일반적으로 신용한도와 동시에 운용될 때는 각 참가기관이 지급불이행기관에 제공한 신용한도를 손실분담기준으로 사용하게 되며 이 경우 각 참가기관은 보다 신중하게 상대신용한도를 설정하게 되는 등 참가기관들에 대하여 리스크 감축을 위한 동기를 부여하는 효과를 기대할 수 있다. 결제부족자금 공동분담은 지급불이행 기관의 사전담보로 결제이행재원을 조달하는 채무불이행자 부담(defaulter pays)과 달리 생존기관(결제이행기관)이 결제이행재원을 분담한다는 점에서 생존자 분담(survivors pay) 방식이라고도 한다.','','ㄱㅈㅂㅈㅈㄱㄱㄷㅂㄷㅈ',ARRAY['결제리스크','차액결제시스템']::text[]),
(20,'결제완결성','지급결제시스템을 통해 이루어진 참가기관의 지급지시가 결제된 이후에는 어떠한 상황 ㄱ 이나 법률에 의해서도 취소되거나 무효화되지 않고 해당 지급결제시스템의 운영 규칙에 따라 무조건적으로 종결되는…','지급결제시스템을 통해 이루어진 참가기관의 지급지시가 결제된 이후에는 어떠한 상황 ㄱ 이나 법률에 의해서도 취소되거나 무효화되지 않고 해당 지급결제시스템의 운영 규칙에 따라 무조건적으로 종결되는 것을 의미한다. 결제완결성(Settlement Finality)이 보장되지 않을 경우 지급결제시스템을 통해 종결된 금융기관의 지급지시가 사후적으로 무효화될 수 있어 금융시스템에 큰 혼란을 초래할 수 있다. 「지급 및 시장인프라 위원회」 (CPMI)와 「국제증권감독기구」(IOSCO)가 제정한 국제기준인 「금융시장인프라에 관한 원칙」(PFMI)에서도 결제완결성 원칙이 규정되어 있어 각국 정책당국이 준수하도록 하고 있다. 우리나라는 2006년 4월 시행된 「채무자회생 및 파산에 관한 법률」에서 지급결제시스템에 대한 결제완결성 보장 제도가 도입되었다. 동 법에 따라 한국은행 총재는 금융위원회 위원장과 협의하여 결제완결성이 보장되는 지급결제시스템을 지정할 수 있으며, 지정된 지급결제시스템을 통해 결제된 지급행위는 참가기관의 파산 등의 사유로 취소할수 없도록 하고 있다.','','ㄱㅈㅇㄱㅅ','{}'::text[]),
(21,'겸업주의/전업주의','하나의 금융회사가 제공할 수 있는 금융서비스의 종류를 어떻게 정하느냐에 따라 겸업주의(Universal banking)와 전업주의(Specialized banking)로 구분된다.','하나의 금융회사가 제공할 수 있는 금융서비스의 종류를 어떻게 정하느냐에 따라 겸업주의(Universal banking)와 전업주의(Specialized banking)로 구분된다. 겸업주의는 한 금융회사가 은행·증권·보험 등 여러 금융서비스를 취급할 수 있는 반면 전업주의는 은행· 증권사·보험사 등이 각각 해당하는 고유의 서비스만을 제공하는 방식이다. 현재 세계적으로 겸업주의가 대세를 이루고 있으나 국가별로는 법적 형태면에서 차이가 있다. 독일, 네덜란드, 스위스 등 대부분의 유럽국가는 은행산업과 증권산업 간에 아무런 장벽을 두지 않고 하나의 은행이라는 법적 조직체 안에서 은행, 증권, 보험 등의 모든 서비스를 제공하는 내부겸업 시스템을 근간으로 한다. 반면에 영국 및 영연방국가, 현재의 미국에서 는 은행이 자회사를 통해 증권이나 보험업무를 수행하는 외부겸업 시스템을 택하고 있다. 전업주의는 종전의 일본 및 미국의 경우처럼 은행산업과 여타 금융서비스 산업의 법적인분리를 특징으로 한다. 우리나라는 과거에 전업주의를 채택하였으나 1980년대 이후 내부겸업을 확대하여 왔으며 2000년 「금융지주회사법」 제정으로 미국, 일본 등과 같은 외부겸업 시스템을 도입하였다. 한편 국외에서는 2008년 글로벌 금융위기의 원인 중 하나로 금융회사의 과도한 금융겸업 확대가 지목되면서 이를 우려하는 목소리가 커지고 있다. 그결과 미국은 은행부문의 헤지펀드 및 사모펀드 운영을 제한하는 볼커룰(Volcker Rule)을 도입하였으며, 영국은 예금·대출 위주의 소매은행으로부터 리스크가 높은 증권투자업무를 분리하는 ‘소매은행업 격리제도(ring-fenced bank)’를 마련하였다.','','ㄱㅇㅈㅇ/ㅈㅇㅈㅇ',ARRAY['볼커룰']::text[]),
(22,'경기','경기(Business Conditions)라는 단어는 일상생활에서 경제적인 형편을 뜻하는 말로 자주 사용된다.','경기(Business Conditions)라는 단어는 일상생활에서 경제적인 형편을 뜻하는 말로 자주 사용된다. 기업들은 매출이 늘고 채산성이 좋아지면 경기가 좋다고 인식할 것이고, 가 계는 임금이 인상되거나 주식, 부동산 등의 자산가격이 올라 살림이 좋아지면 경기가 좋아졌다고 느낄 것이다. 범위를 넓혀 국민경제 전체를 대상으로 볼 때, 경기가 좋다는 것은 생산, 소비, 투자 등의 경제활동이 평균 수준 이상으로 활발한 경우를 의미한다. 장기적관점에서 경기는 항상 일정한 수준을 유지하는 것이 아니라 생산·물가·고용이 상승하는 시기와 하락하는 시기가 주기적으로 순환을 반복하는 경제활동의 상황을 의미한다. 경기는 호황기→후퇴기→불황기→회복기→호황기가 반복되면서 끊임없이 변동하며, 이렇게경기의 일정한 움직임이 되풀이되는 것을 경기의 순환(business cycle)이라고 한다. 이러한 경기의 순환과정은 확장국면과 수축국면이 교대로 되풀이되는 반복성, 여러 측면의 경제활동을 포괄하는 다양성, 확장 및 수축 양상이 시차를 두고 경제 각 부문에 전달되는 파급성, 그리고 일정한 방향으로 계속 확대해 나가는 지속성 등의 특징을 갖는다. 경기를 판단하는 방법으로는 생산, 투자, 고용, 수출 등 경제 각 부문의 여러 경제지표의 움직임을 분석하는 방법, 종합경기지표로 판단하는 방법, 기업가나 소비자들의 경기판단 및 전망설문조사 결과에 의한 방법 등이 있다.','','ㄱㄱ',ARRAY['경기종합지수','동행종합지수']::text[]),
(23,'경기순응성','경기순응성이란 통상 경제주체의 위험인식 및 행위, 금융의 제도 및 규제 등의 효과가 경기변동의 움직임과 같은 방향으로 움직이는 것을 의미한다.','경기순응성이란 통상 경제주체의 위험인식 및 행위, 금융의 제도 및 규제 등의 효과가 경기변동의 움직임과 같은 방향으로 움직이는 것을 의미한다. 예를 들어 은행대출의 경우경기종합지수호경기에는 미래에 대한 낙관적 기대 등으로 여신심사기준도 완화되어 더 크게 증가하여 경기확장에 기여한다. 반면 불경기에는 심사기준이 강화되어 대출이 큰 폭으로 감소하여 불황을 더욱 부추기게 된다. 이러한 은행대출의 경기순응적 행태는 신용팽창 또는 ㄱ 위축을 가속시킴으로서 경기변동의 진폭을 더욱 크게 한다. 따라서 정책당국은 정책을 마련할 경우 경기순응성을 완화할 수 있는 경기대응적 정책수단을 개발하기 위해 노력하고 있다.','','ㄱㄱㅅㅇㅅ',ARRAY['거시건전성 정책']::text[]),
(24,'경기조절정책/경제안정화정책','경기조절정책(Business Adjustment Policy) 또는 경제안정화정책(Stabilization Policy) 은 경기가 지나친 확장 또는 수축 현상을 보일 경우 이를 정상 수준으로…','경기조절정책(Business Adjustment Policy) 또는 경제안정화정책(Stabilization Policy) 은 경기가 지나친 확장 또는 수축 현상을 보일 경우 이를 정상 수준으로 되돌리기 위해 정책당국이 취하는 제반 조치를 말한다. 이는 정책당국이 경제 전체의 총수요 수준을 변동시킴으로써 경기 수위를 조절하는 데 초점을 맞추고 있다. 실제 운영에 있어서는 정부지출과 세율을 조정하는 재정정책이 이용되거나 통화량과 금리 수준을 조절하는 통화정책이 활용된다. 즉 경기가 정상 수준을 큰 폭 밑도는 불황에 직면하게 될 경우 정부는 재정지출을 늘리거나 조세를 줄이는 재정정책 수단을 동원한다. 한편 중앙은행은 통화량을 늘리거나 금리를 내리는 정책수단을 활용한다. 이와는 반대로 경기가 지나치게 과열될 경우정책당국은 재정측면에서는 정부지출을 줄이거나 조세를 늘리고, 통화측면에서는 통화량을 줄이거나 금리를 올리는 조치를 취한다.','','ㄱㄱㅈㅈㅈㅊ/ㄱㅈㅇㅈㅎㅈㅊ',ARRAY['재정정책','통화정책']::text[]),
(25,'경기종합지수','산업생산지수, 소매판매액지수 등 개별 경제지표들은 경제활동의 한 측면만을 반영하고 있어 나라 경제의 전반적인 상황을 종합적으로 파악하기 어렵다.','산업생산지수, 소매판매액지수 등 개별 경제지표들은 경제활동의 한 측면만을 반영하고 있어 나라 경제의 전반적인 상황을 종합적으로 파악하기 어렵다. 이에 따라 개별 경제지표들을 가공·합성하여 경기종합지수(CI; Composite Index)를 작성하고 있다. 경기종합지수는 각 부문별로 경기를 잘 나타내는 경제지표들을 선정한 다음 계절 및 불규칙 요인의 제거, 진폭의 표준화 등의 가공 과정을 거친 후 합산하여 하나의 지수로 만든 것이다. 경기종합지수는 지수의 변동 방향으로 경기변동의 방향을 가늠할 수 있고, 지수의 변동폭으로 경기변동의 크기를 알 수 있기 때문에 경기흐름을 종합적으로 판단하는데 매우 유용하다. 한편, 경기종합지수는 경기에 대한 선·후행 관계에 따라 선행종합지수, 동행종합지수, 후행종합지수로 구분한다. 선행종합지수는 비교적 가까운 장래의 경기 동향을 예측하는 데 활용되며, 동행종합지수는 현재의 경기상태를 판단하는데 이용되고, 후행종합지수는 경기변동을 사후에 확인하는 데 활용된다.','','ㄱㄱㅈㅎㅈㅅ',ARRAY['경기']::text[]),
(26,'경상수지','경상수지는 재화나 서비스를 외국과 사고파는 거래 즉 경상거래의 결과로 나타나는 수지를 말한다.','경상수지는 재화나 서비스를 외국과 사고파는 거래 즉 경상거래의 결과로 나타나는 수지를 말한다. 경상수지는 상품수지, 서비스수지, 본원소득수지 및 이전소득수지로 구성된 다. 그런데 이 항목들은 금융계정 구성항목과 비교하면 상대적으로 안정적인 성격을 지닌거래들로 이루어져 있기 때문에 경제발전 및 정책변화의 효과를 측정하거나 전망하는 데널리 이용된다.','','ㄱㅅㅅㅈ',ARRAY['상품수지','서비스수지','본원소득수지','이전소득수지']::text[]),
(27,'경영실태평가/은행경영실태 평가등급제도','경영실태평가는 금융감독당국이 임점 검사 시 금융기관의 경영실태 전반을 점검·평가 하기 위한 제도로, 각 금융기관의 경영실적, 경영의 건전성, 경영진의 경영능력, 법규준수 상황 및 리스크 관리실태…','경영실태평가는 금융감독당국이 임점 검사 시 금융기관의 경영실태 전반을 점검·평가 하기 위한 제도로, 각 금융기관의 경영실적, 경영의 건전성, 경영진의 경영능력, 법규준수 상황 및 리스크 관리실태 등 다양한 평가부문을 종합적이고 통일적인 방식에 따라 일정한 등급으로 평가하여 금융기관의 경영상태를 체계적이고 객관적으로 확인하는 방법의 하나이다. 아울러 평가 결과에 따라 부실금융기관에 대해 적기시정조치를 취하는 한 편 감독상 주의 및 관심을 더욱 집중하여 금융기관 경영의 건전성 확보와 금융소비자 보호 등 감독·검사 업무의 효율성을 높일 수 있다. 우리나라는 1996년 10월 은행에 도입한 이후 다른 금융기관에 확대 적용하였다. 경영실태평가의 평가절차나 방식 등은 금융기관별로 거의 동일하나, 금융기관 그룹별 특성에 따라 평가부문과 항목에 차이가 있다. 은행의 경우 해당 은행의 특성(일반은행, 외은지점, 특수은행 등)에 따라 CAMEL-IR 경제성장률방식, ROCA 방식, CACREL 방식을 운용하고 있다. 경영실태평가의 부문별 평가등급 및종합등급은 1등급(우수), 2등급(양호), 3등급(보통), 4등급(취약), 5등급(위험)의 5단계로 구분되며, 일반은행의 경우 각 등급을 3단계(+, 0, -)로 세분화하여 5등급, 15단계로 운용 ㄱ 하고 있다.','','ㄱㅇㅅㅌㅍㄱ/ㅇㅎㄱㅇㅅㅌㅍㄱㄷㄱㅈㄷ',ARRAY['CAMEL-IR 방식/ROCA 방식/CACREL 방식']::text[]),
(28,'경제 서프라이즈 지수','경제 서프라이즈 지수는(ESI; Economic Surprise Index)는 실제로 발표된 경제지표가 시장의 전망치(예상치, 컨센서스)와 얼마나 차이가 있는지를 수치로 나타내는 지표이다.','경제 서프라이즈 지수는(ESI; Economic Surprise Index)는 실제로 발표된 경제지표가 시장의 전망치(예상치, 컨센서스)와 얼마나 차이가 있는지를 수치로 나타내는 지표이다. 주요 경제지표(고용, GDP, 소비자물가 등)의 실제 값과 Bloomberg, Reuters 등에서 조사한 시장참가자들의 중간 예측치(컨센서스) 간의 차이를 표준화하여 합산한다. 지수가 양수(+)이면 실제 경제지표가 예상보다 호조이고, 음수(-)이면 예상보다 부진함을 의미한 다. 서프라이즈 지수는 국가별·지역별로 현재 경제 상황이 예상 대비 얼마나 좋은지 또는 나쁜지 파악하는 데 유용하며, 특히 지수가 상승 추세일수록 주식시장 등 위험자산에 긍정적인 신호를 주고, 하락 추세이면 시장 상승의 탄력을 둔화시키는 등 증권 시장의 투자심리에 미치는 영향이 큰 지수이다. 시티그룹, JP모건, Bloomberg 등에서 산출하는 ESI 가 널리 사용된다.','','ㄱㅈㅅㅍㄹㅇㅈㅈㅅ','{}'::text[]),
(29,'경제성장률','경제성장률이란 일정 기간(분기 또는 연간) 중 한 나라의 경제규모, 즉 국민소득 규모가 늘어난 정도를 백분율로 표시한 것이다.','경제성장률이란 일정 기간(분기 또는 연간) 중 한 나라의 경제규모, 즉 국민소득 규모가 늘어난 정도를 백분율로 표시한 것이다. 국민소득은 생산활동의 범위나 생산물의 가치평가 방법 등에 따라 여러 가지 개념으로 나뉘지만, 경제성장률을 계산하는 데 가장 일반적으로 쓰이는 국민소득은 각 경제활동부문에서 창출해낸 실질 부가가치의 합계, 즉 실질국내총생산(실질GDP)이다. 따라서 경제성장률은 대부분의 경우 실질GDP 증가율을 의미한다. 금년 실질GDP - 전년 실질GDP 경제성장률(%) = 전년 실질GDP 한편 수 개년 동안의 연평균 경제성장률을 계산하고자 할 때에는 복리 연율의 산식을 이 용하여 연평균 경제성장률을 산출한다.','','ㄱㅈㅅㅈㄹ',ARRAY['잠재GDP성장률']::text[]),
(30,'경제심리지수','경제심리지수란 한국은행이 기업가 또는 소비자들의 경제에 대한 인식을 조사하여 작성한 지표이며, 대표적으로 조사대상을 기업가로 하는 기업경기실사지수(BSI; Business Survey…','경제심리지수란 한국은행이 기업가 또는 소비자들의 경제에 대한 인식을 조사하여 작성한 지표이며, 대표적으로 조사대상을 기업가로 하는 기업경기실사지수(BSI; Business Survey Index)와 소비자로 하는 소비자동향지수(CSI; Consumer Survey Index)가 있다. 또한 한 국은행은 BSI와 CSI를 합성하여 민간의 경제상황에 대한 인식을 종합적으로 평가할 수 있는 경제심리지수(ESI; Economic Sentiment Index)도 작성·발표하고 있다. ESI는 BSI와 CSI 중 경기연관성이 높은 항목을 선정하여 이들의 표준화지수를 가중평균하는 등의 과정을 거쳐 산출한다. ESI가 100을 넘으면 현재 민간의 경제심리가 과거 평균보다 낙관적임 을, 100 미만이면 과거 평균보다 비관적임을 각각 나타낸다. 이러한 심리지표들은 실물지표와 대체로 높은 상관관계를 보이지만 때로는 미래정보 및 기대수준의 반영 여부, 질적 통계와 양적 통계 간의 조사척도 차이 등에 따라 다소 괴리되는 움직임을 보이기도 한다.','','ㄱㅈㅅㄹㅈㅅ',ARRAY['기업경기실사지수(BSI)','소비자동향지수(CSI)']::text[]),
(31,'경제전망보고서','다양한 경제지표와 세계 경제 동향 등을 바탕으로 향후 경제 상황이 어떻게 전개될지를 분석하고 예측한 보고서를 말한다.','다양한 경제지표와 세계 경제 동향 등을 바탕으로 향후 경제 상황이 어떻게 전개될지를 분석하고 예측한 보고서를 말한다. 경제전망에는 보통 한 나라의 경제가 얼마나 성장할지 예측하는 경제성장률 전망, 물가가 얼마나 오를지 분석하는 인플레이션 전망, 일자리사정을 예측하는 고용 전망, 외환시장 변동성 및 환율을 살펴보는 환율 전망, 수출입 추세와 무역수지를 예측하는 경상수지 전망 등이 포함된다. 경제주체들이 어떤 경제행위를 결정할 때 경기판단과 예측의 정확성 여부에 따라 미래의 경제적 성과가 크게 달라질 수 있으므로 경제전망은 중요하다. 가계는 경제전망에 따라 재화·서비스, 주택, 주식 등의 구입 시기를 결정한다. 기업은 제품에 대한 수요 전망을 통해 생산량과 시설 투자 계획을 수립한다. 중앙은행은 경기 및 물가 전망을 바탕으로 경제성장과 물가안정을 이루기 위해경제활동인구/비경제활동인구/경제활동참가율통화량 및 금리 운용계획을 결정하며, 정부 또한 경제전망에 기초하여 예산 편성, 재정지출 등을 확정한다. 한국은행, IMF, OECD, 각종 민간경제연구소 등 국내외 여러 기관은 정기적으로 경제전망을 발표하고 있다. ㄱ','','ㄱㅈㅈㅁㅂㄱㅅ',ARRAY['경제성장률','인플레이션','경상수지','경기']::text[]),
(32,'경제협력개발기구(OECD)','제2차 세계대전 직후 유럽경제 부흥 지원을 위해 설립되었던 유럽경제협력기구(OEEC)의 18개국과 미국, 캐나다 등 총 20개 선진국이 1961년 9월에 설립한 국제기구이다.','제2차 세계대전 직후 유럽경제 부흥 지원을 위해 설립되었던 유럽경제협력기구(OEEC)의 18개국과 미국, 캐나다 등 총 20개 선진국이 1961년 9월에 설립한 국제기구이다. 설립목적은 회원국의 경제성장과 금융안정을 도모함으로써 세계 경제 발전에 기여하고, 세계 각국의 건전한 경제성장을 촉진하는 한편, 다자주의와 무차별주의에 따라 세계무역 확대에 기여하는 것이다. 회원 가입은 최고의사결정기구인 이사회에서 회원국의 만장일치로 결정한다. 1990년대 들어 신흥시장국 및 체제전환국에 문호를 개방하고, 2000년대에는 외연 확대를 위해 적극 노력하면서 회원국 수는 총 38개국(2025년 6월 말 기준)으로 늘어났다. OECD(Organization for Economic Co-operation and Development)는 이사회, 상임위원회 및 분야별 위원회, 사무국 외에도 각종 부속기구 및 특별기구로 구성되는데, 이사회는 회원국 각료가 참석하는 각료이사회, OECD 주재 회원국 대사가 참여하는 상주대표이사회로 나뉜다. OECD의 활동은 주로 위원회 및 산하 작업반을 통해 이루어지는데, 경제성장과 안정, 국제무역, 개발원조, 금융, 다국적기업, 투자, 통계 등 다양한 분야에서 회원국 간 정책 경험을 공유하고 글로벌 현안에 대한 정책방안을 연구하는 한편 주요 사안에 대한 규범 제정에도 큰 역할을 하고 있다. 우리나라는 1995년 가입신청서 제출 이후가입조건에 대한 협의를 거쳐 1996년 12월에 가입하였다.','','ㄱㅈㅎㄹㄱㅂㄱㄱ()','{}'::text[]),
(33,'경제활동인구/비경제활동인구/ 경제활동참가율','만15세 이상 인구 중 일할 수 있는 능력과 취업의사를 동시에 갖춘 사람을 경제활동인구라 한다.','만15세 이상 인구 중 일할 수 있는 능력과 취업의사를 동시에 갖춘 사람을 경제활동인구라 한다. 경제활동인구는 현재 취업상태에 있는지에 따라 취업자와 실업자로 구분된다. 취업자란 매월 15일이 포함된 1주일 동안에 수입을 목적으로 1시간 이상 일한 사람과 본인 또는 가족이 운영하는 농장이나 사업체에서 주당 18시간 이상 일한 무급가족종사자를 가리킨다. 그밖에 일정한 직장이나 사업장은 가지고 있으나 일시적인 질병, 일기불순, 휴가, 노동쟁의 등의 사유로 조사기간에 일을 하지 않은 사람도 취업자로 분류된다. 실업자란 적극적으로 일자리를 구해보았으나 일을 하지 못한 사람으로서 즉시 취업이 가능한 사람을 말한다. 한편 15세 이상 인구 중 경제활동인구에 포함되지 않은 사람, 즉 조사대상기간에 취업도 실업도 아닌 상태에 있는 사람은 비경제활동인구로 분류된다. 비경제활동인구에는 집안에서 가사와 육아를 도맡아 하는 전업주부, 학교에 다니는 학생, 일을 할 수없는 연로자와 심신장애자, 구직단념자 등이 포함된다. 경제활동참가율은 15세 이상 인구에 대한 경제활동인구의 비율을 말한다. 경제활동인구(취업자 + 실업자) 경제활동참가율 = ×100 15세 이상 인구','','ㄱㅈㅎㄷㅇㄱ/ㅂㄱㅈㅎㄷㅇㄱ/ㄱㅈㅎㄷㅊㄱㅇ',ARRAY['고용보조지표','잠재경제활동인구']::text[]),
(34,'경제후생지표','복지지표로서 한계성을 갖는 국민총소득(GNI)을 보완하기 위해 미국의 노드하우스(W. Nordhaus)와 토빈(J. Tobin)이 제안한 새로운 지표를 말한다.','복지지표로서 한계성을 갖는 국민총소득(GNI)을 보완하기 위해 미국의 노드하우스(W. Nordhaus)와 토빈(J. Tobin)이 제안한 새로운 지표를 말한다. 현재 주요 지표로 활용 중인 국민총소득은 국민 복지에 영향을 미치는 많은 요인(주부의 가사노동, 여가, 공해 등)을 포괄하지 못하고 있어 국민 생활의 질적 수준 또는 복지수준을 정확히 반영하지 못하는 단점을 갖고 있다. 이를 감안하여 경제후생지표(MEW; Measure of Economic Welfare) 는 국민총소득에 후생요소를 추가하고, 비후생요소를 제외함으로써 복지수준을 정확히반영하려는 취지로 제안되었다. 하지만 통계작성에 있어 후생 및 비후생 요소의 수량화가 쉽지 않아 널리 사용되지는 못하고 있는 실정이다.','','ㄱㅈㅎㅅㅈㅍ',ARRAY['국민총소득(GNI)']::text[]),
(35,'경직적 물가지수','소비자물가지수를 구성하는 품목들은 가격이 경직적으로 움직이는 품목과 신축적으로 움직이는 품목으로 나누어 볼 수 있는데, 그중 경직적으로 움직이는 품목들을 대상으로 만든계좌대체물가지수를 경직적…','소비자물가지수를 구성하는 품목들은 가격이 경직적으로 움직이는 품목과 신축적으로 움직이는 품목으로 나누어 볼 수 있는데, 그중 경직적으로 움직이는 품목들을 대상으로 만든계좌대체물가지수를 경직적 물가지수, 신축적으로 움직이는 품목을 대상으로 한 물가지수를 신축적 물가지수라고 한다. 정부의 직·간접적인 영향을 크게 받는 공공서비스, 전기·수도, 담배, 보육·급식 가격이나 개인서비스 요금 등은 대체로 가격이 쉽게 오르거나 내리지 않는 ㄱ 특징을 보이므로 경직적 물가를 구성하는 주요 품목이다. 이러한 경직적 물가의 변동은 장기적인 인플레이션 흐름을 잘 반영하므로 향후 물가 기조를 예측하는데 유용한 지표이다.','','ㄱㅈㅈㅁㄱㅈㅅ',ARRAY['근원인플레이션율']::text[]),
(36,'계절변동조정시계열','경제의 움직임은 주로 일, 주, 월, 분기 또는 연간 등 일정기간을 기준으로 통계를 수집하여 파악하는데 이를 시계열이라 한다.','경제의 움직임은 주로 일, 주, 월, 분기 또는 연간 등 일정기간을 기준으로 통계를 수집하여 파악하는데 이를 시계열이라 한다. 대부분의 경제분석은 시계열의 수준보다는 변동을 대상으로 한다. 시계열의 변동요인은 크게 추세, 순환, 계절 및 불규칙 요인의 네 가지로 구분할 수 있다. 특히 시계열에서 주기적으로 나타나는 기후나 명절 등과 같은 사회적 관습은 매년 반복되는 특성이 있는데 이를 계절변동요인이라 한다. 이러한 계절변동을 고 려하지 않고 기간별로 시계열의 증감을 비교하면 오류가 있을 수 있다. 특히 전월 또는 전분기 대비 증감은 계절변동을 조정하지 않고 계산하면 많은 왜곡이 있게 된다. 계절변동조정시계열은 원래의 시계열에서 계절요인을 여러 통계적 기법을 이용하여 제거한 것을 말한다. 이때 일반적으로 예측 가능한 불규칙요인도 함께 제거한다. 한편 계절변동요인은 연간단위로 나타나므로 연간시계열에는 적용되지 않으며, 전년동기대비는 각 기간의 계절변동요인이 같다고 판단하여 원래의 시계열을 이용한다.','','ㄱㅈㅂㄷㅈㅈㅅㄱㅇ',ARRAY['경제성장률']::text[]),
(37,'계좌대체','증권거래시 실물증권을 주고받는 대신 양자 모두 계좌를 가진 중앙예탁기관 내에서 계좌간 이전하는 방식으로 장부상 처리하는 것을 말한다.','증권거래시 실물증권을 주고받는 대신 양자 모두 계좌를 가진 중앙예탁기관 내에서 계좌간 이전하는 방식으로 장부상 처리하는 것을 말한다. 주식ㆍ채권 등 증권거래의 결과 매도자의 증권을 매수자에게 이전해야 한다. 그런데 증권의 이전을 위한 실물증권의 인도 방식은 자본시장에서 이루어지는 증권의 대량거래와 잦은 소유자 변동 등을 감안하면 사실상 불가능하다. 따라서 대부분의 국가에서는 중앙예탁기관의 계좌대체 방식으로 증권의 소유권을 이전하고 있으며 우리나라도 한국예탁결제원이 계좌간 대체 방식으로 증권 이전을 처리하고 있다.','','ㄱㅈㄷㅊ',ARRAY['중앙예탁기관']::text[]),
(38,'고객확인절차(KYC)','고객확인절차(KYC; Know Your Customer)는 테러자금조달 및 자금세탁 등 불법거래차단을 위해 관계당국이 부여한 의무에 따라 고객의 신원을 식별하고 확인하는(verify) 업무절차를…','고객확인절차(KYC; Know Your Customer)는 테러자금조달 및 자금세탁 등 불법거래차단을 위해 관계당국이 부여한 의무에 따라 고객의 신원을 식별하고 확인하는(verify) 업무절차를 뜻한다.','','ㄱㄱㅎㅇㅈㅊ()',ARRAY['가상통화','비트코인']::text[]),
(39,'고용률','고용률은 통계청에서 매월 실시하고 있는 경제활동인구조사를 통해 집계된 15세 이상 인구 중에서 취업자가 차지하는 비율을 말한다.','고용률은 통계청에서 매월 실시하고 있는 경제활동인구조사를 통해 집계된 15세 이상 인구 중에서 취업자가 차지하는 비율을 말한다. 한편 실업률은 경제활동인구 중에서 실업자가 차지하는 비율을 말한다. 고용률은 실업률 통계의 한계점을 해소할 수 있기 때문에 고용통계에서 중요한 개념이다. 즉, 고용통계에서 취업준비자와 구직단념자는 실질적인의미에서 실업자이나 비경제활동인구로 분류됨에 따라 이들이 늘어나면 실업률은 낮아질수 있어 체감 실업률과 차이를 느끼게 한다. 그러나 고용률은 15세 이상 인구를 기준으로 계산되기 때문에 실업자와 비경제활동인구간의 이동 등에 따른 경제활동인구수 변동으로 부터 영향을 받지 않는다는 장점이 있다. 다만 고용률도 근로시간이 18시간 미만인 단시간근로자 및 일시휴직자 등 불완전취업자가 증가하는 경우에는 국민들이 체감하는 고용상황과 차이를 보일 수 있다. 고용률(%) = 취업자 / 15세이상인구 × 100 실업률(%) = 실업자 / 경제활동인구 × 100','','ㄱㅇㄹ',ARRAY['고용보조지표','실업률']::text[]),
(40,'고용보조지표','국제노동기구(ILO)에서는 노동 공급과 수요가 일치하지 않아서 일하고 싶은 욕구가 있음 ㄱ 에도 불구하고 일을 하고 있지 못하는 노동력의 크기를 나타내는 고용보조지표를 새로이 확정(2013월…','국제노동기구(ILO)에서는 노동 공급과 수요가 일치하지 않아서 일하고 싶은 욕구가 있음 ㄱ 에도 불구하고 일을 하고 있지 못하는 노동력의 크기를 나타내는 고용보조지표를 새로이 확정(2013월 10월)한 바 있다. 우리나라 통계청에서도 기존의 공식 실업률만으로는 노동시장을 제대로 반영하는데 한계가 있다고 판단하여 2014년 11월부터 새로운 고용보조지표를 발표하고 있다. 고용보조지표는 실업률을 추계하기 위한 공식적인 실업자 이외에 아르바이트 등 단기근로를 하지만 재취업을 원하는 사람(시간관련 추가취업 가능자), 최근구직활동을 안했을 뿐 취업의사가 있고 취업 가능성이 있는 사람(잠재구직자), 그리고 구직노력을 했으나 육아 등으로 당장 일을 시작하지 못하는 사람(잠재취업가능자) 등을 포함 한다. 여기서 비경제활동인구에 포함된 잠재 취업가능자와 잠재 구직자를 합하여 잠재경제활동인구라고 하고, 이를 기존의 경제활동인구와 합산하여 확장경제활동인구라 한다. 현재 고용보조지표는 그 포괄범위에 따라 세 가지 형태로 작성하여 공표되고 있다. 고용보조지표1은 경제활동인구 대비 기존의 취업자 중 시간관련 추가 취업가능자와 실업자의 비율이며, 고용보조지표2는 실업자와 잠재경제활동인구의 합을 확장경제활동인구로 나누어구한다. 한편 고용보조지표3은 확장경제활동인구 대비 시간관련 추가취업 가능자, 실업자및 잠재경제활동인구를 더한 수치의 비율이다. 최근 발표되고 있는 고용보조지표를 보면기존의 공식 실업률과 상당한 차이를 보이고 있는데, 이는 단시간 근로자가 많거나 취업을 희망하고 있지만 구직활동을 하지 않은 사람 등이 그만큼 많다는 것을 의미한다.','','ㄱㅇㅂㅈㅈㅍ',ARRAY['생산유발효과']::text[]),
(41,'고정금리','고정금리란 최초 약정한 금리가 만기까지 그대로 유지되는 금리를 의미하며 변동금리란 일정 주기별로 시장금리를 반영하여 약정금리가 변동하는 금리를 의미한다.','고정금리란 최초 약정한 금리가 만기까지 그대로 유지되는 금리를 의미하며 변동금리란 일정 주기별로 시장금리를 반영하여 약정금리가 변동하는 금리를 의미한다. 예를 들어 만기 1년, 약정금리는 4%의 고정금리라면 약정기간 1년 동안 시장금리가 어떻게 변하더라도 해당 약정금리는 4%이다. 반면 만기 1년, 변동주기 3개월, 약정금리는 CD금리+0.5%(또는 50bp)의 변동금리라면 3개월에 한 번씩 변동된 CD금리에 연동하여 약정금리가 변하게 된다. 예를 들어 CD금리가 최초 약정시 3.0%, 약정 3개월후 3.2%, 6 개월후 3.5%, 9개월후 4.0%라면 약정금리는 최초 약정시 3.5%, 약정 3개월후 3.7%, 6 개월후 4.0%, 9개월후 4.5%가 된다. 자금 차입자 입장에서는 앞으로 시장금리가 상승할것으로 예상하는 경우에는 고정금리를 이용하는 것이 유리하고 시장금리가 하락할 것으로 예상하는 경우에는 변동금리를 이용하는 것이 유리하다. 시장금리 상승 방향의 금리변동에 따른 주택담보대출 차입자의 리스크를 완화하고 재무건전성을 유지하기 위해 정부가 고정금리대출을 장려하는 것도 이런 이유 때문이다. 일반적으로 동일 만기에서는 고정금리가 변동금리보다 높은데 이는 자금 대여자(은행)에게 약정 기간중 금리 변동에 따른 위험 프리미엄이 존재하기 때문이다.','','ㄱㅈㄱㄹ',ARRAY['변동금리','양도성예금증서(CD)']::text[]),
(42,'고정금리부채권(SB)','고정금리부채권(Straight Bond)이란 정해진 기일에 고정된 이자를 지급하고 정해진 만기에 원금을 지급하는 가장 일반적인 형태의 채권으로 전환사채(CB; Convertible Bond)의','고정금리부채권(Straight Bond)이란 정해진 기일에 고정된 이자를 지급하고 정해진 만기에 원금을 지급하는 가장 일반적인 형태의 채권으로 전환사채(CB; Convertible Bond)의','','ㄱㅈㄱㄹㅂㅊㄱ()','{}'::text[]),
(43,'고정이하여신비율','주식전환권과 같이 특별한 조건이 없는 채권을 말한다.','주식전환권과 같이 특별한 조건이 없는 채권을 말한다. 회사채, 국채 등 대부분의 채권이 고정금리부로 발행된다. 이에 대비되는 채권으로 변동금리부채권(FRN; Floating Rate Note)이 있다. 이는 정해진 기일에 특정 금리(예: 국내에서는 3개월 CD금리, 해외에서는 ㄱ 무위험지표금리(RFR; Risk-Free Rate))에 연동된 금리를 지급하고 정해진 만기에 원금을 지급하는 채권이다. 고정금리부채권에 대한 투자는 향후 금리 하락이 예상될 때 유리하며 금리 상승이 예상될 때에는 변동금리부채권에 투자하는 것이 유리하다. 한편 인플레이션이 심할 때 인플레이션을 헤지하기 위한 목적으로 발행되는 채권이 물가연동채권인데 이 는 원금과 이자가 물가상승률(주로 CPI 사용)에 연동하여 증가한다는 면에서 변동금리부채권과 구별된다.','','ㄱㅈㅇㅎㅇㅅㅂㅇ',ARRAY['자산건전성 분류']::text[]),
(44,'고정자본소모','생산활동에는 공장, 기계설비 등 고정자본(시설)이 필요한데 이들은 생산활동 과정에서 마모되기 마련이다.','생산활동에는 공장, 기계설비 등 고정자본(시설)이 필요한데 이들은 생산활동 과정에서 마모되기 마련이다. 이처럼 생산에 이용된 기계 등 자산의 가치 감소분을 고정자본소모 (Consumption of Fixed Capital)라고 한다. 따라서 일정 기간 중에 생산된 생산물의 순수한 가치를 평가하기 위해서는 현재의 생산능력이 저하되지 않고 그대로 유지된 상태에 서 생산이 이루어지는 것으로 하여야 한다. 즉 고정자본소모만큼 조정하여야 한다. 순생산액 = 총생산액(= 산출액 - 중간투입액) - 고정자본소모 (순소득) (총소득) 자동차공장을 예를 들어보면 먼저 자동차를 만들기 위해서는 차체 등 각종 부품이 있어야 하며 또 각종 부품을 조립하는 기계가 있어야 한다. 자동차를 만들게 되면 부품도 소모되지만, 조립기계도 닳게 된다. 여기에서 총생산액은 산출액에서 부품구입액 등 중간투입액을 차감한 총부가가치를 말하고 순생산액은 총부가가치에서 고정자본소모를 뺀 순부가가 치이다. 그런데 고정자본소모는 현 수준의 생산활동을 지속하기 위하여 언젠가는 지출될부분이므로 이 공장의 측면에서 보면 총생산보다는 본래의 기계 가치를 그대로 유지하면서 새로이 생산해 낸 부가가치 즉 순생산이 더욱 의미가 있을 것이다.','','ㄱㅈㅈㅂㅅㅁ',ARRAY['총고정자본형성']::text[]),
(45,'고정환율제도/자유변동환율제도','환율제도는 고정환율제도(Fixed Exchange Rate System)와 자유변동환율제도(Free Floating Exchange Rate System)를 양극단으로 하여 이를 절충하는 다양한…','환율제도는 고정환율제도(Fixed Exchange Rate System)와 자유변동환율제도(Free Floating Exchange Rate System)를 양극단으로 하여 이를 절충하는 다양한 형태로 분류될 수 있다. 고정환율제도는 환율을 정부나 중앙은행이 적정하다고 판단하는 수준으로 일정하게 유지하는 제도이다. 반면 자유변동환율제도는 환율이 외환의 수요와 공급에 의 해 자율적으로 결정되도록 하는 환율제도를 말한다. 고정환율제도는 환율 변동에 따른 충격을 완화하고 거시경제정책의 자율성을 어느 정도 확보할 수 있다는 장점이 있으나 이 를 위해서는 자본이동의 제약이 불가피하여 결과적으로 외화유동성이 부족해질 가능성이 있다. 이 경우 대외불균형이 지속되거나 기초경제여건이 악화되면 환투기공격에 쉽게골디락스경제노출되는 단점이 있다. 반면 자유변동환율제도에서는 자본이동이 자유롭게 이루어지므로 외화유동성 확보가 용이하고 외부충격이 환율 변동에 의해 흡수됨으로써 거시경제정책의 자율적 수행이 수월한 장점이 있다. 다만 외환시장 규모가 작고 외부충격의 흡수 능력 ㄱ 이 부족한 신흥국은 환율 변동성의 확대가 경제의 교란 요인으로 작용할 가능성이 크다. 한편 어떤 환율제도를 채택하더라도 ① 통화정책의 자율성 ② 자유로운 자본이동 ③ 환율 안정 등 세 가지 정책목표를 동시에 달성하기는 현실적으로 어려운데, 이를 삼불원칙 (impossible trinity 또는 trilemma)이라고 한다.','','ㄱㅈㅎㅇㅈㄷ/ㅈㅇㅂㄷㅎㅇㅈㄷ',ARRAY['삼불원칙','외환시장']::text[]),
(46,'고통지수','소비자물가상승률과 실업률을 더한 값으로 1975년 미국의 경제학자 오쿤(A. Okun)이 국민의 삶에 실업률과 물가상승률이 큰 영향을 준다는 점에 착안하여 만든 국민의 삶의 질을 측정하기 위한…','소비자물가상승률과 실업률을 더한 값으로 1975년 미국의 경제학자 오쿤(A. Okun)이 국민의 삶에 실업률과 물가상승률이 큰 영향을 준다는 점에 착안하여 만든 국민의 삶의 질을 측정하기 위한 지표이다. 이 수치가 높을수록 실업자는 늘고 물가는 높아져 한 나 라의 국민이 느끼는 삶의 고통이 늘어남을 의미한다. 그러나 고통지수(Misery Index)를 절대적인 것으로 생각해 나라 간에 단순 비교하기는 어려운 측면이 있는데 이는 나라별로 소비자물가상승률과 실업률을 계산하는 기준이 다르고 빈부격차나 조사대상에 따라서도 느끼는 고통의 정도가 상이할 수 있기 때문이다. 한편 고통지수가 발표된 이후 이를 보완한 다양한 지표들이 개발되고 있는데, 1999년 미국 하버드대 배로(R. Barro)교수는 오쿤의 고통지수에 국민소득증가율과 이자율을 감안한 ‘배로고통지수’(BMI; Barro Misery Index)를 발표한 바 있다.','','ㄱㅌㅈㅅ',ARRAY['소비자물가지수(CPI)','실업률']::text[]),
(47,'골디락스경제','골디락스경제(Goldilocks Economy)는 경기과열에 따른 인플레이션과 경기침체에 따른 실업을 염려할 필요가 없는 최적 상태에 있는 건실한 경제를 가리킨다.','골디락스경제(Goldilocks Economy)는 경기과열에 따른 인플레이션과 경기침체에 따른 실업을 염려할 필요가 없는 최적 상태에 있는 건실한 경제를 가리킨다. 이는 영국의 전래동화인 골디락스와 곰 세 마리(Goldilocks and the three bears)에 등장하는 금발머리 소녀의 이름에서 유래하였다. 동화에 따르면 엄마 곰이 끓인 뜨거운 수프를 큰 접시와 중간 접시 그리고 작은 접시에 담은 후 가족이 이를 식히기 위해 산책을 나갔는데, 이 때집에 들어온 골디락스가 아기 곰 접시에 담긴 너무 뜨겁지도 않고 너무 차지도 않은 적당한 온도의 수프를 먹고 기뻐하는 상태를 경제에 비유한 것이라 한다. 즉 경기과열이나 불황으로 인한 높은 수준의 인플레이션이나 실업률을 경험하지 않는 양호한 상태가 지속되는 경제를 지칭한다.','','ㄱㄷㄹㅅㄱㅈ',ARRAY['대안정기','장기침체']::text[]),
(48,'공개시장운영','공개시장운영(Open Market Operation)은 중앙은행이 금융시장에서 금융기관을 상대로 증권을 매매하여 시중유동성이나 시장금리 수준에 영향을 미치는 통화정책수단이다.','공개시장운영(Open Market Operation)은 중앙은행이 금융시장에서 금융기관을 상대로 증권을 매매하여 시중유동성이나 시장금리 수준에 영향을 미치는 통화정책수단이다. 공개시장운영은 다른 통화정책수단(지급준비제도, 여수신제도 등)에 비해 시기와 규모를 신축적으로 정할 수 있고 금융시장의 가격메커니즘에 따라 이루어지므로 시장친화적인 데다 즉각적인 매매거래만으로 신속하게 정책을 시행할 수 있다는 장점이 있어 대부분의 선진국 중앙은행들은 공개시장운영을 주된 통화정책수단으로 사용하고 있다. 우리나라의 경우한국은행이 공개시장운영을 통해 금융기관의 지급준비금(지준) 보유 규모를 변동시킴으로 써 콜금리가 기준금리에서 크게 벗어나지 않도록 조정한다. 즉 금융기관의 지준 부족(보유지준 ＜ 필요지준)으로 콜머니가 증가하고 콜금리 상승압력이 증대될 경우 한국은행은 RP 매입 등을 통해 지준을 공급하여 콜금리의 상승을 제한하며, 반대로 지준 잉여(보유지준 ＞ 필요지준)로 콜론이 증가하고 콜금리 하락압력이 증대될 경우에는 RP매각, 통화안정증권발행, 통화안정계정 예치 등을 통해 잉여 지준을 흡수하여 콜금리의 하락을 제한한다.','','ㄱㄱㅅㅈㅇㅇ',ARRAY['통화정책수단']::text[]),
(49,'공공재','공공재는 모든 개인이 공동으로 이용할 수 있는 재화 또는 서비스를 의미한다.','공공재는 모든 개인이 공동으로 이용할 수 있는 재화 또는 서비스를 의미한다. 국방·경찰·소방·공원·도로 등과 같이 정부에 의해서만 공급할 수 있는 것이라든가 또는 정부에 의해서 공급되는 것이 바람직하다고 사회적으로 판단되는 재화 또는 서비스가 이에 해당한다. 공공재에는 보통 시장가격은 존재하지 않으며 수익자부담 원칙도 적용되지 않는다. 공급사용표(SUT) 따라서 공공재 규모의 결정은 정치기구에 맡길 수밖에 없다. 공공재의 성질로는 어떤 사람의 소비가 다른 사람의 소비를 방해하지 않고 여러 사람이 동시에 편익을 받을 수 있는 비경쟁성·비선택성, 대가를 지급하지 않은 특정 개인을 소비에서 제외하지 않는 비배제성 ㄱ 등을 들 수 있다.','','ㄱㄱㅈ',ARRAY['자유재']::text[]),
(50,'공급병목','제품이나 서비스가 생산자로부터 소비자에게 전달되는 특정 단계에서 목이 좁은 병 입구처럼 원활한 흐름이 이루어지지 않아 전체 공급망이 지연되거나 막히는 현상을 말한다.','제품이나 서비스가 생산자로부터 소비자에게 전달되는 특정 단계에서 목이 좁은 병 입구처럼 원활한 흐름이 이루어지지 않아 전체 공급망이 지연되거나 막히는 현상을 말한다. 공급 과정에서 중간에 한 부분이 막히면 아무리 다른 단계가 정상적이어도 전체 흐름이 느려지거나 정지하게 된다. 예를 들어 반도체와 같은 부품이 부족하면 자동차, 전자제품을 비롯한 많은 생산공정이 차질을 빚는다. 항만 적체, 컨테이너 부족 등으로 물류가 지연되거나 코로나19, 우크라이나 전쟁 등으로 글로벌 공급망이 붕괴되면 생산 및 유통과정에 병목이 발생한다. 이처럼 공급병목이 생기면 관련된 물품의 공급 부족으로 물가가 상승하고, 제조업체의 생산 계획에 영향을 미치며, 배송 지연 등으로 소비자의 불편을 초래하고 나아가 경제 전반의 성장세가 둔화되어 경기가 나빠지게 된다.','','ㄱㄱㅂㅁ',ARRAY['글로벌 공급망 압력지수','경기']::text[]),
(51,'공급사용표(SUT)','산업연관표는 투입산출표(Input-Output Tables)와 공급사용표(Supply and Use Tables)로 구성되는데, 투입산출표는 상품을 기준으로, 공급사용표는 산업을 기준으로…','산업연관표는 투입산출표(Input-Output Tables)와 공급사용표(Supply and Use Tables)로 구성되는데, 투입산출표는 상품을 기준으로, 공급사용표는 산업을 기준으로 생산내역을 나타낸 표이다. 투입산출표는 상품을 기준으로 하기 때문에 하나의 산업에 서 한 상품만을 생산한다고 가정하고 있어 경제 현실이 제대로 반영되지 못하는 문제점을 갖고 있는 반면, 공급사용표는 경제 현실이 잘 반영될 뿐만 아니라 국민소득통계, 국민대차대조표 등 국민경제 통계들 간의 정합성 유지에도 중요한 역할을 한다. 공급사용표는 공급표(Supply Table)와 사용표(Use Table)로 구성된다. 공급표의 세로 방향은 각산업에서 어떤 상품이 얼마만큼 생산(또는 공급)되는가를 기록하여 산업별 상품의 생산구조를 알려준다. 가로 방향은 각 상품이 어느 산업에서 얼마만큼 생산되어 공급되는가를 표시하여 상품의 산업별 공급구조를 나타내고 있다. 한편 사용표의 세로방향은 각 산업의 생산활동에 투입되는 중간재와 부가가치를 기록하고 있으며, 가로 방향은 공급된 상품이 각 산업별 중간수요 또는 소비, 고정자본형성, 재고증감, 수출 등 최종수요로 사용된 내역을 나타낸다.','','ㄱㄱㅅㅇㅍ()',ARRAY['국민계정체계(SNA)','국민대차대조표']::text[]),
(52,'공급탄력성','공급탄력성은 가격변화에 대한 공급의 민감도를 측정하는 척도이다.','공급탄력성은 가격변화에 대한 공급의 민감도를 측정하는 척도이다. 공급탄력성은 공급량의 변화율을 가격의 변화율로 나누어 측정한다(공급량의 변화율÷가격의 변화율). 만일 1%의 가격 상승이 1%보다 더 큰 공급량 증가를 가져오면 공급은 탄력적이라 하며, 1%의 가격 상승이 1%보다 더 적은 공급량 증가를 가져오면 공급은 비탄력적이라 한다. 공급량변화율과 가격변화율이 같다면 공급탄력성은 1이고, 공급은 단위 탄력적이라 한다. 또한, 어떤 재화의 공급량이 가격변동에 전혀 영향을 받지 않는다면 공급의 가격탄력성은 영(0) 이고, 이 재화의 공급은 완전 비탄력적이라 하며 이 재화의 공급곡선은 수직선의 형태를 보인다. 반대로 한 재화의 공급곡선이 수평선일 때 이 재화의 공급은 완전 탄력적이며 공급탄력성은 무한대(∞)가 된다. 공급탄력성은 가격의 상승과 하락에 맞춰 공급량을 조절하는 생산자의 능력에 따라 달라진다.','','ㄱㄱㅌㄹㅅ',ARRAY['수요탄력성']::text[]),
(53,'공동부유','공동부유(共同富裕, Common Prosperity)는 시진핑 중국 국가주석이 2021년 이후 강조한 주요 정책 방향 중 하나로서 소수만 부유해지는 것이 아니라 사회 전체가 균형 있게 번영하고…','공동부유(共同富裕, Common Prosperity)는 시진핑 중국 국가주석이 2021년 이후 강조한 주요 정책 방향 중 하나로서 소수만 부유해지는 것이 아니라 사회 전체가 균형 있게 번영하고 부를 나누어 모든 국민이 함께 잘사는 사회를 만들자는 것을 의미한다. 즉 독과점기업의 불공정 거래행위 시정, 기업의 사회 기부 독려, 부동산세 도입 등을 통해 부의 불균형을 해소하고 국민 전체의 삶의 질 향상을 도모하려는 정책이다. 공동부유가 핵심정책으로 등장한 배경으로는 중국경제가 개혁·개방 이후 고도성장을 달성하는 데 성공하였으나','','ㄱㄷㅂㅇ','{}'::text[]),
(54,'관리통화제도','관리통화제도는 금본위제도와는 달리 중앙은행이 통화량을 직접 조절하여 경제를 안정시키는 제도이다.','관리통화제도는 금본위제도와는 달리 중앙은행이 통화량을 직접 조절하여 경제를 안정시키는 제도이다. 금본위제도에서는 국가가 보유한 금의 양에 따라 통화 발행이 제한되며, 통화의 가치는 금에 의해 보장되었다. 한편 관리통화제도에서는 중앙은행이 금과 같은 실물자산의 보유 규모와 관계없이 물가안정, 경기 조절, 환율 관리 등을 목적으로 통화 공급을 유연하게 조절한다. 이때 중앙은행은 기준금리 조정, 공개시장운영, 지급준비율 변경등 주요 정책수단 등을 통해 인플레이션을 억제하거나 경기를 조절한다. 20세기 중반 이 후 대부분의 국가들은 관리통화제도로 전환하였으며, 이에 따라 각국의 중앙은행은 통화정책을 통해 경제운영에 있어 핵심적인 역할을 담당하고 있다.','','ㄱㄹㅌㅎㅈㄷ',ARRAY['금본위제도']::text[]),
(55,'광의통화(M2)','광의통화(M2)는 경제 내에 유통되는 화폐규모를 측정하는 통화지표의 하나로서, 지급결제기능을 중시하여 작성하는 협의통화(M1) 외에도 약간의 이자소득 손실을 감수한다면언제든지 인출이 가능한…','광의통화(M2)는 경제 내에 유통되는 화폐규모를 측정하는 통화지표의 하나로서, 지급결제기능을 중시하여 작성하는 협의통화(M1) 외에도 약간의 이자소득 손실을 감수한다면언제든지 인출이 가능한 가치저장기능이 있는 금융상품까지 포함된다. 만기 2년 이내의 정기예금, 정기적금, 금융채, 수익증권 등 단기간 내 현금화가 가능한 금융상품이 이에 해당한다. M2는 중장기적인 통화량 흐름과 금융시장의 유동성 상황을 파악하는 데 활용되며, 중앙은행의 통화정책 수립에도 중요한 기준이 된다. 일반적으로 M2가 증가하면 시중에 돈이 많이 풀렸다는 의미로 해석되며, 이는 물가 상승 압력이나 경기과열 가능성과도 연결된다. M2는 협의통화보다 유동성은 낮지만, 실제 경제에서 통화량을 측정할 때 가장 널리 사용되는 지표다.','','ㄱㅇㅌㅎ()',ARRAY['통화지표','통화량']::text[]),
(56,'교환사채(EB)','교환사채(EB; Exchangeable Bond)란 사채권자의 의사에 따라 교환사채 발행기업이 보유하고 있는 타사 주식 등 여타의 유가증권과 교환할 수 있는 선택권이 부여된 사채를 구독경제말한다.','교환사채(EB; Exchangeable Bond)란 사채권자의 의사에 따라 교환사채 발행기업이 보유하고 있는 타사 주식 등 여타의 유가증권과 교환할 수 있는 선택권이 부여된 사채를 구독경제말한다. 발행하는 채권에 주식이 연계되어 있다는 점에서 발행회사의 신주를 일정한 조건으로 매수할 수 있는 신주인수권부사채(BW; Bonds with Warrant)나, 발행회사의 주식으로 전환할 수 있는 권리가 부여된 전환사채(CB; Convertible Bond) 등과 함께 주식연 ㄱ 계증권으로 불린다. 발행회사가 보유하는 교환대상 유가증권은 상장유가증권으로 제한되고 있으며 증권예탁원에 의무적으로 예탁되어야 한다. 발행회사는 낮은 이자율로 사채를 발행하여 금융비용 부담을 덜 수 있어 회사채 발행을 통한 기업자금조달을 촉진할 수 있는 장점이 있다. 반면에 투자자의 입장에서도 비교적 안정적인 데다 미래의 주식가격 상승에 따른 시세차익을 기대할 수 있음에 따라 유리한 투자수단이 된다. 교환이 이루어질때 발행기업의 자산과 부채가 동시에 감소한다. 신규자금 유입이 없다는 점에서 신주인수권부사채(BW)와는 다르고 신주발행에 따른 자본금의 증가가 없다는 점에서 전환사채 (CB)와도 다르다.','','ㄱㅎㅅㅊ()',ARRAY['신주인수권부사채(BW)','전환사채(CB)']::text[]),
(57,'교환성 통화','국제적인 통용력을 가진 특정 국가의 통화를 말한다.','국제적인 통용력을 가진 특정 국가의 통화를 말한다. 현재는 외환시장에서 미국의 달러화와 자유로이 교환 가능한 통화라는 의미로 사용되고 있다. 국제통화기금(IMF)에서는 IMF 협정 제8조에 따라 회원국은 자국 통화에 교환성을 부여할 의무를 부여받고 있다. 이 조항에 따라 자국 통화의 교환성을 유지하는 국가를 ‘IMF 8조국’이라 하는데, 이들 국가의 통화를 교환성 통화(Convertible Currency)로 볼 수 있다. 그러나 좁은 의미로는 SDR 가치산정에 사용되는 바스켓 통화의 요건에 자유사용가능성(freely usable criterion)이 포함 되어 있어서 현재 SDR 바스켓을 구성하고 있는 미 달러화, 유로화, 파운드화, 엔화 및 위안화를 교환성 통화로 볼 수 있다.','','ㄱㅎㅅㅌㅎ',ARRAY['기축통화','특별인출권(SDR)','복수통화바스켓제도']::text[]),
(58,'구독경제','소비자가 제품이나 서비스를 소유하지 않은 채 일정한 금액을 주기적으로 지불하면서 사용하는 경제 모델을 말한다.','소비자가 제품이나 서비스를 소유하지 않은 채 일정한 금액을 주기적으로 지불하면서 사용하는 경제 모델을 말한다. 즉, 사는 것이 아니라 빌려 쓰고 구독하는 것에 초점을 둔소비 방식이다. 월간 또는 연간 등 정기 결제로 제품 또는 서비스를 이용하면서 소유 대신사용 권한을 얻게 된다. 소비자의 입장에서는 구독경제가 초기 비용 부담이 적고 다양한 서비스를 체험할 수 있다는 점에서 유리하다. 다만 장기적으로 비용이 누적될 수 있고, 구독 해지를 놓쳐 불필요한 지출이 생기기도 한다. 공급자의 입장에서는 사용자의 취향, 소비 습관에 맞춰 적절한 정보를 제공하여 고객을 꾸준히 유지함으로써 장기 고객을 확보하는 것이 비즈니스의 핵심이 된다.','','ㄱㄷㄱㅈ','{}'::text[]),
(59,'구매력평가 환율','구매력평가(PPP; Purchasing Power Parity) 환율은 해당 통화의 실질 구매력을 기준으로 평가한 환율이다.','구매력평가(PPP; Purchasing Power Parity) 환율은 해당 통화의 실질 구매력을 기준으로 평가한 환율이다. 이는 관련 당사국 간 물가수준(또는 물가상승률) 차이 즉, 당사국 화폐 간 실질구매력(가치)의 차이에 의해 균형 환율이 결정된다는 구매력평가이론에 근거하고 있다. 예를 들어 스타벅스 커피의 가격이 우리나라에서 5,000원이고 미국에서 5달러라면 원/달러 환율은 1,000원이어야 한다는 것이다. 대표적 구매력평가환율로는 각국의 맥도날드 햄버거 가격을 비교해 환율을 산출하는 ‘빅맥지수’를 들 수 있다. PPP 환율은 국가 간 화폐의 교환비율이라기보다는 자국화폐의 실질구매력을 나타내게 되는데, 국가 간 물가수준 차이를 고려하여 GDP 등의 통계를 국가 간에 비교하는 데 흔히 사용된다. OECD, UN, IMF 등 국제기구에서 작성하고 있다.','','ㄱㅁㄹㅍㄱㅎㅇ',ARRAY['빅맥지수','일물일가의 법칙','금리평가이론']::text[]),
(60,'구인배수','노동의 수요와 공급 상황을 나타내는 지표로서 일자리수를 취업 희망자수로 나누어 구하는데 인력수급동향을 파악하는데 주로 이용된다.','노동의 수요와 공급 상황을 나타내는 지표로서 일자리수를 취업 희망자수로 나누어 구하는데 인력수급동향을 파악하는데 주로 이용된다. 예를 들어 구인배수 0.7은 취업 희망자열 명당 일곱 개의 일자리가 있다는 의미로 수치가 높을수록 고용사정이 좋다는 것을 의 미 한다. 우리나라의 경우 1986년부터 작성하여 왔다. 외환위기 이전에는 구인배수가 1 을 웃돌아 일자리가 남는 경우도 있었지만, 그 이후에는 대개의 경우 구인배수가 1에 못미치는 것이 일반적이어서 최근의 고용사정이 과거에 비해 좋지 않다는 것으로 해석된다.','','ㄱㅇㅂㅅ',ARRAY['고용률','실업률갭']::text[]),
(61,'국가경쟁력','국가경쟁력은 한 나라가 경제성장을 지속하고, 국민들의 삶의 질을 향상시킬 수 있는 능 ㄱ 력을 말한다.','국가경쟁력은 한 나라가 경제성장을 지속하고, 국민들의 삶의 질을 향상시킬 수 있는 능 ㄱ 력을 말한다. 대표적인 국가경쟁력 지표로 스위스 국제경영개발원(IMD)에서 발표하는 세계경쟁력순위(WCR; World Competitiveness Ranking)가 있다. 국제경영개발원은 기업 활동을 효율적으로 가능하게 하는 제도적ㆍ경제적 조건을 갖추고 있느냐를 국가경쟁력의 핵심으로 보고 주요 통계지표와 기업인 및 연구원 대상 설문조사 결과를 종합하여세계 70여개 국가의 경쟁력을 평가한다. 세계경쟁력순위는 경제 운용 성과, 정부의 효율성, 기업의 경영 효율성, 사회간접자본 등 4개 부문으로 구성되어 있다.','','ㄱㄱㄱㅈㄹ','{}'::text[]),
(62,'국가신용등급','한 나라가 채무를 이행할 능력과 의사가 얼마나 있는지를 평가하여 등급으로 표시한 것으로 국제금융시장에서 차입금리나 투자여건을 판단하는 기준이 된다.','한 나라가 채무를 이행할 능력과 의사가 얼마나 있는지를 평가하여 등급으로 표시한 것으로 국제금융시장에서 차입금리나 투자여건을 판단하는 기준이 된다. 미국의 스탠더드& 푸어스(S&P), 무디스(Moody’s), 영국의 피치(Fitch) 등 국제신용평가기관은 해당국의 정치체제의 안정성, 국가안보상의 위험 등 정치적인 요소와 경제성장률, 외채 규모, 대외 채무불이행 경험 등 경제적인 요소를 종합적으로 고려하여 국가신용등급을 평가한다. 국가 신용등급(Sovereign Credit Rating)은 정부채무의 표시통화에 따라 외화표시 채무등급과 국내통화표시 채무등급으로, 만기구성에 따라 단기채무등급과 장기채무등급으로 각각 구분된다. 또한, 신용도에 따라 크게 투자등급과 투기등급으로 구분되는데, 투기등급에 해당하는 신용도를 가진 국가에 대한 투자는 그만큼 위험하다고 할 수 있다. 한편 국가신용등 급은 해당국 내의 기업이나 금융기관의 개별 신용등급을 결정하는 하나의 기준이 된다. 따라서 국가신용등급이 상향조정되면 해당국의 정부는 물론 기업, 금융기관 등이 더 낮은 가 산금리(위험 프리미엄)로 외화자금을 조달할 수 있어 외화차입 비용을 크게 줄일 수 있다.','','ㄱㄱㅅㅇㄷㄱ',ARRAY['무디스','스탠더드&푸어스']::text[]),
(63,'국가채무','국가채무란 정부가 재정적자 보전 등을 목적으로 국내외로부터 자금을 차입함으로써 발생하는 채무를 말한다.','국가채무란 정부가 재정적자 보전 등을 목적으로 국내외로부터 자금을 차입함으로써 발생하는 채무를 말한다. 국가채무는 한 번 누적되면 새로운 재정적자가 발생하지 않더라도 기존채무에 대한 이자지급 부담으로 채무가 계속 늘어나는 자기증식의 속성을 가지고 있다. 또한 기대인플레이션이나 시장금리를 상승시키는 부작용이 있을 수 있다. 이에 따라각국은 안정적인 자금조달 및 국채시장 유지, 자금조달의 비용최소화 등 재정의 지속가능성 유지를 위해 국가채무를 적절히 분석·관리하고 있다. 국가채무를 분석할 경우에는 주로 명목GDP대비 비율을 사용하며 채무의 보유주체, 만기구조 등 채무의 질적 구성을 고 려하기도 한다.','','ㄱㄱㅊㅁ',ARRAY['기대인플레이션']::text[]),
(64,'국고금 실시간 전자이체','국고금 실시간 전자이체란 정부가 지급할 국고금이 실시간으로 각 채권자의 예금계좌로 바로 입금되게 하는 것을 말한다.','국고금 실시간 전자이체란 정부가 지급할 국고금이 실시간으로 각 채권자의 예금계좌로 바로 입금되게 하는 것을 말한다. 정부의 통합재정정보시스템(dBrain+, 구 NAFIS)과 한 국은행 및 금융기관의 전산시스템을 연결해 2003년 1월부터 시행되었다. 일반 국민이나 기업들은 정부에 물품이나 용역을 제공한 후 그 대금으로 국고수표를 받는 대신 자신이 거래하는 금융기관의 계좌로 받기 때문에 예전처럼 정부 또는 지자체를 찾아가 국고수표를 받아 이를 금융기관에 다시 입금하는 수고를 덜게 되었다. 특히 이 시스템이 도입되면서 정부는 별도로 국고수표를 발행할 필요성이 없어 국고금 관리 행정업무의 효율화는 물론 국고수표 인쇄비용도 절감할 수 있게 되었다.','','ㄱㄱㄱㅅㅅㄱㅈㅈㅇㅊ',ARRAY['국고수표','국고전산망']::text[]),
(65,'국고대리점','국가의 경제활동도 민간의 경제활동과 마찬가지로 금전 수수를 수반하게 되는데 이와 같은 경제활동에 수반되는 일체의 현금을 통상 국고금이라 한다.','국가의 경제활동도 민간의 경제활동과 마찬가지로 금전 수수를 수반하게 되는데 이와 같은 경제활동에 수반되는 일체의 현금을 통상 국고금이라 한다. 우리나라에서는 국고금의 출납사무를 중앙은행인 한국은행이 담당하고 있다. 그러나 한국은행의 한정된 조직과 인력만으로는 전국의 국고금 납부자에게 충분한 편의를 제공하기 어렵기 때문에 한국은행은 금융기관과의 계약을 통해 금융기관 영업점을 국고 대리점으로 지정하여 국고금 수납사무를 위탁하고 있다. 국고대리점은 국고수납대리점과 국고금수납점으로 구분하는데 기능상 차이는 없으며 계약방식의 차이에 의해서 구분된다. 국고수납대리점은 은행 영업점국내공급물가지수및 신용협동기구의 중앙회가 이에 해당되며 국고금수납점은 신용협동기구의 중앙회 등이 산하 회원조합(금고)에 국고금 수납사무를 재위탁한 영업점을 말한다. 2025년 6월말 현재국고대리점은 총 16,467개(국고수납대리점 5,647개, 국고금수납점 10,820개)가 있다. ㄱ','','ㄱㄱㄷㄹㅈ','{}'::text[]),
(66,'국고수표','국고수표는 지출관이 국고금 지출을 위하여 발행하는 수표로 과거 국고금의 기본지급수단이었으나 2003년 1월 1일 「국고금관리법」의 시행으로 국고금 실시간 전자이체제도가 실시됨으로써 국고금…','국고수표는 지출관이 국고금 지출을 위하여 발행하는 수표로 과거 국고금의 기본지급수단이었으나 2003년 1월 1일 「국고금관리법」의 시행으로 국고금 실시간 전자이체제도가 실시됨으로써 국고금 지급방식이 국고수표 사용방식에서 수취인의 예금계좌로 바로 입금되도록 변경된 이후 사용하지 않고 있다. 다만 금융기관의 전산장애 등과 같은 비상시를 위해 폐지하지 않고 있다.','','ㄱㄱㅅㅍ',ARRAY['국고금 실시간 전자이체','국고전산망']::text[]),
(67,'국고전산망','2003년 1월 한국은행이 국고업무를 전자적으로 처리하기 위하여 구축한 전산망을 국고 전산망이라고 말하며 정부(디지털예산·회계시스템(dBrain+)), 한국은행, 금융기관(우정사업본부 포함) 및…','2003년 1월 한국은행이 국고업무를 전자적으로 처리하기 위하여 구축한 전산망을 국고 전산망이라고 말하며 정부(디지털예산·회계시스템(dBrain+)), 한국은행, 금융기관(우정사업본부 포함) 및 금융결제원의 전산시스템을 서버접속 방식으로 연결한다. 국고전산망을 이용하여 취급하는 업무는 OLTP(On-line Real Time Transaction Processing) 방식으로 처리하는 실시간 전자이체업무와 FTP(File Transfer Protocol) 방식으로 처리하는 파일 송수신업무가 있다. 국고전산망 참가대상 기관은 기획재정부, 한국은행과 국고수납대리점계약을 체결한 금융기관 및 한국은행 이외의 국고금수납기관(체신관서, 금융결제원)으로 한정하고 있다. 국고전산망 운영시간은 오전 9시부터 오후 4시까지이다.','','ㄱㄱㅈㅅㅁ',ARRAY['국고금 실시간 전자이체']::text[]),
(68,'국내공급물가지수','국내공급물가지수는 생산자물가지수와 수입물가지수를 결합하여 국내시장에 공급되는 상품 및 서비스의 종합적인 가격 수준을 지수화한 것이다.','국내공급물가지수는 생산자물가지수와 수입물가지수를 결합하여 국내시장에 공급되는 상품 및 서비스의 종합적인 가격 수준을 지수화한 것이다. 국내공급물가지수는 생산단계별, 즉 원재료, 중간재 및 최종재로 지수가 구분되기 때문에 물가변동의 파급과정을 파악하는 데 용이하다. 현재 우리나라뿐만 아니라 미국, 일본, 캐나다 등 주요 선진국에서도 국내공급물가지수에 해당하는 통계를 작성하고 있다.','','ㄱㄴㄱㄱㅁㄱㅈㅅ',ARRAY['생산자물가지수(PPI)','수출입물가지수']::text[]),
(69,'국내총생산(GDP)','국내총생산(GDP; Gross Domestic Product)은 한 나라의 영역 내에서 가계, 기업, 정부등 모든 경제주체가 일정 기간 생산활동에 참여하여 창출한 부가가치 또는 최종 생산물을…','국내총생산(GDP; Gross Domestic Product)은 한 나라의 영역 내에서 가계, 기업, 정부등 모든 경제주체가 일정 기간 생산활동에 참여하여 창출한 부가가치 또는 최종 생산물을 시장가격으로 평가한 합계로서 여기에는 국내에 거주하는 비거주자(외국인)에게 지급되는 소득도 포함된다. 한편 가격의 적용방법에 따라 명목GDP(Nominal GDP)와 실질 GDP(Real GDP)로 구분되는데, 명목GDP는 국가경제의 규모나 구조 등을 파악하는 데사용되며 실질GDP는 경제성장, 경기변동 등 전반적인 경제활동의 흐름을 분석하는 데이용된다.','','ㄱㄴㅊㅅㅅ()',ARRAY['국민총소득(GNI)']::text[]),
(70,'국내총투자율','국내총투자율(Gross Domestic Investment Ratio)은 국민경제가 구매한 재화 중에서 자산의 증가로 나타난 부분이 국민총처분가능소득에서 차지하는 비율을 의미한다.','국내총투자율(Gross Domestic Investment Ratio)은 국민경제가 구매한 재화 중에서 자산의 증가로 나타난 부분이 국민총처분가능소득에서 차지하는 비율을 의미한다. 국민경제 내에서 자산의 증가에 쓰인 모든 재화는 고정자산과 재고자산으로 구분되는데 전자를 국내총고정자본형성 또는 고정투자, 후자를 재고증감 또는 재고투자라 하며 이들의 합계를 총자본형성 또는 국내총투자라고 부른다. 따라서 국내총투자율은 국민총처분가능소득에 대한 총자본형성의 비율이다.','','ㄱㄴㅊㅌㅈㅇ',ARRAY['국민총처분가능소득']::text[]),
(71,'국민계정체계(SNA)','국민계정은 국민경제의 순환과 변동을 체계적으로 기록한 사회회계로서 경제활동을 거 ㄱ 래형태별 및 거래에 참가하는 경제주체별로 파악하여 복식부기 방식으로 기록한 것이다.','국민계정은 국민경제의 순환과 변동을 체계적으로 기록한 사회회계로서 경제활동을 거 ㄱ 래형태별 및 거래에 참가하는 경제주체별로 파악하여 복식부기 방식으로 기록한 것이다. 즉, 국민경제의 순환에 따른 변동을 각각의 거래형태와 거래주체 간의 상호연관 하에서 체계적으로 작성한 것이다. 국민계정체계(SNA; System of National Accounts)는 기존의 산업연관표, 국민소득통계, 자금순환표, 국제수지표 등 별개로 파악하고 있던 국민계정관련 통계를 통합, 각종 경제분석에 적합하도록 거래형태 및 거래주체를 경제활동의 동질성에 따라 몇 가지 부문으로 나누어 체계적으로 작성한 것이다. 국민계정체계는 재화와 서비스의 생산 활동을 보여주는 생산계정, 소득의 분배와 사용을 나타내는 소득계정, 비금융자산의 취득과 처분 등을 기록하는 자본계정, 금융 자산 및 부채의 취득과 처분을 기록하는 금융계정, 거주자와 비거주자 간 거래를 기록하는 국외계정, 일정시점에서 경제전체의 자산과 부채 현황을 보여주는 대차대조표계정 등의 기본 체계로 구성된다.','','ㄱㅁㄱㅈㅊㄱ()',ARRAY['‌국내총생산(GDP)','산업연관표(I/O Tables)','국민대차대조표','국제수지표']::text[]),
(72,'국민대차대조표','국민대차대조표(National Balance Sheet)는 특정 시점에서 국민경제 또는 비금융법인기업, 금융법인기업, 일반정부, 가계 및 비영리단체, 국외 등 각 경제주체가 보유하고 있는 유·무형…','국민대차대조표(National Balance Sheet)는 특정 시점에서 국민경제 또는 비금융법인기업, 금융법인기업, 일반정부, 가계 및 비영리단체, 국외 등 각 경제주체가 보유하고 있는 유·무형 실물자산 및 금융자산/부채의 가액과, 자산에서 부채를 차감한 순자산을 기록한 스톡통계이다. 즉, 국민대차대조표는 경제주체별로 처분가능한 금융 및 비금융자산의 가 액 등 재산상태를 나타내며 그중 순자산(net wealth)은 해당 경제주체의 재산상태를 집약한 정보라 할 수 있다. 특히 국민경제 전체의 순자산은 흔히 국부(national wealth)라 불리며 국내경제가 보유한 비금융자산의 현재가액과 국외부문에 대한 순금융자산청구권의 합계와 동일하다. 국민대차대조표에 기록되는 자산 항목은 크게 비금융자산과 금융자산/ 금융부채로 구성된다. 비금융자산의 경우 생산과정을 통해 산출된 것이냐의 여부에 따라생산자산과 비생산자산으로 나누어지고, 비금융비생산자산에는 생산과정을 거치지 않고 자연적으로 존재하는 토지, 지하자원, 입목 등이 포함된다. 한편, 국민대차대조표는 기초대차대조표, 기말대차대조표 및 대차대조표 증감계정으로 구성되어 있어 각 경제주체의 재산이 기간 중에 어떠한 요인에 의해 변동하였는지를 몇 가지로 분해하여 보여주는 표로 서 SNA 내에서 소득창출 과정 등을 기록한 플로계정과 자산의 축적상태를 기록한 스톡계정을 통합하는 기능을 수행한다. 2014년에 국민대차대조표를 신규 편제함으로써 우리나 라는 SNA(System of National Accounts) 이행의 최상위인 6단계를 달성하게 되었고 완전한 국민계정체계를 구현하게 되었다.','','ㄱㅁㄷㅊㄷㅈㅍ',ARRAY['국민계정체계(SNA)']::text[]),
(73,'국민부담률','국민부담률(total tax revenue as percentage of GDP)이란 조세와 사회보장기여금이 명목 국내총생산(GDP)에서 차지하는 비중(조세부담률+사회보장부담률)을 말한다.','국민부담률(total tax revenue as percentage of GDP)이란 조세와 사회보장기여금이 명목 국내총생산(GDP)에서 차지하는 비중(조세부담률+사회보장부담률)을 말한다. 이는 조세를 명목GDP로 나눈 조세부담률과 국민이 부담하는 사회보장기여금을 명목GDP로 나눈 사회보장부담률을 합친 개념이다. 따라서 조세부담률보다 포괄적으로 국민부담 수준을 측정하는 지표이다. 조세부담률이 국민의 조세부담을 나타내는 대표적 지표이기는 하나 국민들이 강제적으로 납부해야 하는 연금 및 사회보험의 부담은 나타내지 못한다는 한계가 있다. 이러한 점을 감안하여 OECD는 미래에 보장급부를 받을 수 있는 권한을 부여하는 모든 강제적인 납부액 즉, 사회보장기여금(social security contributions)을 일종의 조세로 분류하여 국민부담률을 산출하고 있다. 국민들은 강제성이라는 특성 때문에 국민연금, 건강보험, 고용보험 등의 사회보장기여금을 세금과 비슷하게 인식하는 경향이 강하므로 국민부담률이 실제 국민들이 체감하는 부담 수준을 더 정확히 나타낸다고 볼 수있다.','','ㄱㅁㅂㄷㄹ',ARRAY['조세부담률']::text[]),
(74,'국민소득','국민소득(NI; National Income)은 한 나라 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 자본 및 경영에 대한 대가인 영업잉여의 합계로서…','국민소득(NI; National Income)은 한 나라 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 자본 및 경영에 대한 대가인 영업잉여의 합계로서 고정자본소모와 순생산 및 수입세는 포함되지 않는다. 즉 한 나라 국민이 벌어들인순수한 소득을 나타내는 지표로서 다음과 같이 산출한다.','','ㄱㅁㅅㄷ','{}'::text[]),
(75,'국민연금','국민소득(NI) = 국민총소득 - 고정자본소모 - 생산 및 수입세 + 보조금 = 국민순소득 - 생산 및 수입세 + 보조금 = 국민순소득 - 순생산 및 수입세 ㄱ = 피용자보수 + 영업잉여 = 임금…','국민소득(NI) = 국민총소득 - 고정자본소모 - 생산 및 수입세 + 보조금 = 국민순소득 - 생산 및 수입세 + 보조금 = 국민순소득 - 순생산 및 수입세 ㄱ = 피용자보수 + 영업잉여 = 임금 + 지대 + 이자 + 이윤','','ㄱㅁㅇㄱ',ARRAY['합계출산율','인구고령화']::text[]),
(76,'국민처분가능소득(NDI)/ 국민총처분가능소득(GNDI)','국민처분가능소득(NDI; National Disposable Income)은 나라 경제 전체가 소비나 저축으로 자유로이 처분할 수 있는 소득으로서 거주자와 비거주자 간의 소득이전이 반영된 것이다.','국민처분가능소득(NDI; National Disposable Income)은 나라 경제 전체가 소비나 저축으로 자유로이 처분할 수 있는 소득으로서 거주자와 비거주자 간의 소득이전이 반영된 것이다. 국민처분가능소득은 국민순소득(NNI; Net National Income)에 교포송금 등과 같이 생산활동과는 관계없이 외국으로부터 받은 소득(국외수취경상이전)을 더하고 무상원조 등 외국에 지급한 소득(국외지급경상이전)을 차감하여 산출한다. 한편 국민처분가능소득에 고정자본소모를 더한 것을 국민총처분가능소득(GNDI; Gross National Disposable Income)이라고 하는데 소비와 저축을 국민총처분가능소득으로 나누어 구한 값을 각각 평균소비성향, 평균저축성향이라고 한다. 국민총처분가능소득은 총저축률과 총투자율을 산출하는데도 이용된다. 국민처분가능소득(NDI) = 국민순소득* + 국외순수취경상이전** * 국외순수취 영업이익 및 재산소득이 반영된 피용자보수 및 영업이익 + 순생산 및 수입세 ** ‌교포송금 등과 같이 생산활동과는 관계없이 외국으로부터 받은 소득(국외수취경상이전)에서 무상원조 등으로 외국에 지급한 소득(국외지급경상이전)을 뺀 금액국민총처분가능소득(GNDI) = 국민처분가능소득 + 고정자본소모 = 최종소비지출 + 총저축','','ㄱㅁㅊㅂㄱㄴㅅㄷ()/ㄱㅁㅊㅊㅂㄱㄴㅅㄷ()',ARRAY['국민총소득(GNI)']::text[]),
(77,'국민총소득(GNI)','국민총소득(GNI; Gross National Income)은 한 나라의 국민이 일정 기간 동안 벌어들인 ㄱ 임금, 이자, 배당 등의 소득을 모두 합친 것이다.','국민총소득(GNI; Gross National Income)은 한 나라의 국민이 일정 기간 동안 벌어들인 ㄱ 임금, 이자, 배당 등의 소득을 모두 합친 것이다. 국가 간에는 재화와 서비스는 물론 노동이나 자본과 같은 생산요소도 활발하게 거래되고 있다. 한 나라의 기업이 다른 나라 사람을 고용하여 생산을 하기도 하고 반대로 그 나라 국민이 다른 나라에 나가 생산활동에 참여하기도 한다. 여기서 생산요소의 국가 간 이동을 고려하여 거주성 측면, 즉 한 나라의 국민을 기준으로 소득을 측정한 것이 국민총소득이다. 국민총소득(명목기준)은 GDP(명목기준) 에다 한 나라의 국민(거주자)이 다른 나라에서 벌어들인 소득(국외수취요소소득)을 더하고, 다른 나라 국민(비거주자)이 그 나라에서 벌어들인 소득(국외지급요소소득)을 뺀 금액이다. 다시 말해서 국민총소득(명목기준)은 GDP에 국외순수취요소소득을 더하여 산출된다. 다 만 실질기준 국민총소득은 실질구매력을 반영하기 위하여 실질GDP에다 국외순수취요소소득뿐만 아니라 교역조건 변화에 따른 실질무역손익까지 고려하여 산출한다. 국민총소득에서 고정자본소모를 제외하면 국민순소득(NNI; Net National Income)이 된다.','','ㄱㅁㅊㅅㄷ()',ARRAY['국내총생산(GDP)','국외순수취요소소득']::text[]),
(78,'국부펀드','국부펀드(Sovereign Fund)는 주로 투자수익을 목적으로 다양한 종류의 국내외 자산에 투자·운용하는 국가 보유 투자기금을 말한다.','국부펀드(Sovereign Fund)는 주로 투자수익을 목적으로 다양한 종류의 국내외 자산에 투자·운용하는 국가 보유 투자기금을 말한다. 국부펀드는 운용목적이나 투자자산 선택 등에 서 사모펀드, 연기금 등과 유사한 면이 있으나 소유권이 민간이 아니라 국가에 있다는 점에서 근본적인 차이가 있다. 국부펀드의 종류는 재원을 조달하는 방법에 따라 상품펀드와 비상품펀드로 나누어진다. 상품펀드의 재원은 국가기관의 원자재 수출대금 또는 민간기업의 원자재 수출소득에 대한 세금 등 정부의 외화수입으로 조달되며 비상품펀드의 경우는 국제수지 흑자로 축적된 외환보유액, 공적연기금, 재정잉여금 등으로 조달된다. 국부펀드라는 용어가 널리 사용되기 시작한 것은 2005년경이나, 1953년 쿠웨이트투자청 등 이 있었으며 대부분의 국부펀드는 1970년대 이후에 만들어졌다. 2000년대 이후 국부펀드는 아시아와 중동을 비롯한 신흥시장국가들이 주로 조성하여 왔다. 이들은 석유수출과 경상수지 흑자를 통해 벌어들인 외환보유액을 이용하여 국부펀드를 설립하여 운용하고 있다. 우리나라는 2005년 7월 한국투자공사(KIC; Korea Investment Corporation)를 설립하였다. 이후에도 2007년 중국에서 중국투자공사(CIC; China Investment Corporation), 2008년에는 러시아에서 러시아 National Welfare Fund 등이 설립되었다.','','ㄱㅂㅍㄷ',ARRAY['국내총생산(GDP)','국민총소득(GNI)']::text[]),
(79,'국외투자율','에서도 투자가 저축을 초과하게 되면 부족한 돈을 국외로부터 조달하게 되는데 이를 국외저축(foreign savings)이라고 한다.','에서도 투자가 저축을 초과하게 되면 부족한 돈을 국외로부터 조달하게 되는데 이를 국외저축(foreign savings)이라고 한다. 국외저축이 양(+)인 것은 경상수지 적자에 대응되며 경상수지 적자는 순대외채무(=대외채무-대외채권)의 증가로 보전된다. ㄱ','','ㄱㅇㅌㅈㅇ',ARRAY['국민총처분가능소득','총투자율','국내총투자율','총저축률']::text[]),
(80,'국제결제은행(BIS)','BIS(BIS; Bank for International Settlements)는 1930년 헤이그협정을 모체로 설립된 세계에서 가장 오래된 국제금융기구로서 중앙은행 간 정책협력을 주요기능으로…','BIS(BIS; Bank for International Settlements)는 1930년 헤이그협정을 모체로 설립된 세계에서 가장 오래된 국제금융기구로서 중앙은행 간 정책협력을 주요기능으로 하고 있으며 현재 60개 중앙은행이 회원으로 참여하고 있다. BIS는 중앙은행 간 협력체로서의 기능 수행에 중점을 두고 있으나 국제금융거래의 원활화를 위한 편의 제공, 국제결제업무와 관련한 수탁자 및 대리인으로서의 역할도 수행하고 있다. BIS는 최고의사결정기구인 총회, 운영을 담당하는 이사회, 일반업무를 관장하는 집행부로 구성되어 있으며 중앙은행간 정보교환기능 제고를 위해 총재회의, 특별회의, 각종 산하 위원회 회의 등을 수시로 개최하고 있다. 또한, 아시아지역과 아메리카지역 중앙은행과의 관계를 증진하기 위하여 홍콩 및 멕시코에 지역사무소를 개설하였다. 한국은행은 1975년 연차총회에 옵서버 자격으로 참석한 이래 국제통화협력을 위해 노력한 결과 1997년 1월 14일 정식회원으로 가입하였다.','','ㄱㅈㄱㅈㅇㅎ()','{}'::text[]);
